// Question banks: aek, gases, nuclear, organic1, organic2, labdata.
// Convention: first 5 are warm-ups, the next 20 are CCC/CCO/USNCO style.
import type { QuizQ } from './framework';

export const AEK_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'aek-001', topic: 'aek', skill: 'acids/ph-calc', q: 'pH of 0.01 M HCl?', opts: ['1', '12', '2', '0.01'], a: 2, why: 'This is asking for the pH of a strong acid solution. A strong acid dissociates completely, so [H⁺] equals the acid concentration. Here [H⁺] = 0.01 = 10⁻² mol/L, and pH = −log[H⁺] = 2.', misconception: '<b>Strong</b> and <b>concentrated</b> are unrelated words. Strong describes how <em>completely</em> an acid dissociates — a property of the substance. Concentrated describes how <em>much</em> of it is in the solution — a property of the mixture. This 0.01 M HCl is a strong acid at a low concentration. Compare 1 M acetic acid (weak but concentrated, pH 2.4) with 0.001 M HCl (strong but dilute, pH 3.0): the <em>weak</em> acid is the more acidic solution of the two. Neither word predicts the other, so never reach for "strong ⇒ low pH".' },
  { id: 'aek-002', topic: 'aek', skill: 'acids/ph-calc', q: 'At 25 °C, pH + pOH = ?', opts: ['7', '10', '1', '14'], a: 3, why: 'This is asking how pH and pOH are related in water at 25 °C. Water self-ionises so that [H⁺][OH⁻] = Kw = 1.0 × 10⁻¹⁴. Taking −log of both sides turns that product into a sum: pH + pOH = 14.' },
  { id: 'aek-003', topic: 'aek', skill: 'redox/oxidation-states', q: 'Oxidation is the ______ of electrons.', opts: ['loss', 'gain', 'sharing', 'pairing'], a: 0, why: 'This is asking what oxidation means in terms of electrons. Oxidation is the loss of electrons by a substance. Reduction is the opposite, a gain of electrons, and the two always happen together.' },
  { id: 'aek-004', topic: 'aek', skill: 'acids/ph-calc', q: 'A pH of 3 compared to pH 5 is…', opts: ['2× more acidic', '100× more acidic', '2 units more basic', '10× more acidic'], a: 1, why: 'This is asking how much more acidic pH 3 is than pH 5. The pH scale is logarithmic, so each unit is a tenfold change in [H⁺]. Two units apart means 10 × 10 = 100 times more hydrogen ions.' },
  { id: 'aek-005', topic: 'aek', skill: 'kinetics/arrhenius', q: 'Raising temperature generally makes reactions…', opts: ['slower', 'unchanged', 'faster', 'reverse'], a: 2, why: 'This is asking what heating does to a reaction rate. Molecules only react if they collide with at least the activation energy, the minimum energy the reaction needs. Heating gives a larger fraction of them that much energy, so the reaction speeds up.' },
  // ---- olympiad ----
  { id: 'aek-006', topic: 'aek', skill: 'acids/titration-curves', q: 'Halfway to equivalence in a weak acid–strong base titration, pH = …', opts: ['7', 'pKb', '½ pKa', 'pKa of the acid'], a: 3, why: '[HA] = [A⁻] → Henderson–Hasselbalch gives pH = pKa exactly. This is how pKa is measured.', misconception: 'Half-equivalence is where pH = pKa, and it has nothing to do with pH 7. At that point exactly half the acid has been converted, so [HA] = [A⁻] and the log term in Henderson–Hasselbalch vanishes. The <em>equivalence</em> point is a different place entirely — pH 7 only for a strong acid with a strong base, and above 7 for any weak acid.' },
  { id: 'aek-007', topic: 'aek', skill: 'redox/cell-potential', q: 'You multiply a half-reaction by 2. Its E°…', opts: ['is unchanged', 'halves', 'doubles', 'flips sign'], a: 0, why: 'Potential is INTENSIVE. (ΔG° = −nFE° scales instead, through n.)', misconception: 'E° is intensive: multiplying a half-reaction changes nothing about its potential. Doubling 2H⁺ + 2e⁻ → H₂ does not double 0.00 V, because potential is energy <em>per coulomb</em> and both halves of that ratio scale together. What does scale is ΔG° = −nFE°, through n — which is exactly why you combine half-reactions by adding ΔG°, not by adding E° values, whenever n differs.' , why2: 'Look at the units. A volt is a joule per coulomb — a <em>ratio</em>. Doubling the half-reaction doubles the joules released and doubles the coulombs passed, so the quotient is unchanged, exactly as heating twice as much water to the same temperature does not make it twice as hot. E° belongs with temperature, density and pressure (intensive); ΔG°, n, mass and charge scale with size (extensive). The practical consequence is worth more than the fact itself: you may never add E° values to build a new half-reaction. Convert each to ΔG° = −nFE°, add those, and divide by the new n — which is why E° for Fe³⁺/Fe is not E°(Fe³⁺/Fe²⁺) + E°(Fe²⁺/Fe).' },
  { id: 'aek-008', topic: 'aek', skill: 'kinetics/integrated-rate', q: 'First-order reaction, t½ = 10 min. Fraction left after 30 min?', opts: ['1/3', '1/8', '1/6', '1/9'], a: 1, why: '3 half-lives → (½)³ = 1/8. First-order t½ never depends on concentration.' },
  { id: 'aek-009', topic: 'aek', skill: 'acids/buffers', q: 'Which mixture is a buffer?', opts: ['HCl + NaCl', 'NaOH + NaCl', 'CH₃COOH + CH₃COONa', 'HNO₃ + NaNO₃'], a: 2, why: 'A buffer needs a WEAK conjugate pair. Strong acids\' conjugates (Cl⁻, NO₃⁻) have no appetite for protons.' },
  { id: 'aek-010', topic: 'aek', skill: 'kinetics/mechanisms', q: 'The experimental rate law reflects the mechanism\'s…', opts: ['slowest step', 'fastest step', 'overall equation', 'final step'], a: 0, why: 'The rate-determining step is the bottleneck; overall coefficients only give orders for single-step (elementary) reactions.', misconception: 'Rate-law exponents come from <em>experiment</em>, never from reading the coefficients off the balanced equation. For 2NO + O₂ → 2NO₂ the balanced equation tempts you into rate = k[NO]²[O₂], and there it happens to be right — but for H₂ + Br₂ → 2HBr the measured rate law is k[H₂][Br₂]^½, which no coefficient could have told you. Only an <em>elementary</em> step lets you read orders off stoichiometry, and you can never know a step is elementary just by looking at it.' },
  { id: 'aek-011', topic: 'aek', skill: 'redox/cell-potential', q: 'In a galvanic cell, electrons flow…', opts: ['cathode → anode', 'cation → anion', 'through the salt bridge', 'anode → cathode'], a: 3, why: 'Oxidation at the anode releases electrons into the wire. "An Ox, Red Cat."', misconception: 'Electrons leave the anode and travel through the external wire to the cathode — they never cross the salt bridge. The salt bridge carries <em>ions</em>, and it exists to keep both compartments electrically neutral; without it the cell stops within moments even though the metals and wire are untouched. Drawing electron flow through the bridge is a mechanism that cannot work: electrons do not swim through electrolyte solutions.' },
  { id: 'aek-012', tier: 3, topic: 'aek', skill: 'acids/ph-calc', q: 'pH of 0.10 M weak acid with Ka = 1.0×10⁻⁵?', opts: ['1.0', '5.0', '3.0', '2.5'], a: 2, why: 'x ≈ √(KaC) = √(10⁻⁶) = 10⁻³ M → pH = 3.00. (x is 1% of C — approximation valid.)', misconception: 'pH = pKa holds only at half-neutralisation, not for an acid simply dissolved in water — answering 5.0 is reading pKa off the Ka and stopping there. Nor is a weak acid fully ionised: 0.10 M would only give pH 1.0 if every molecule dissociated, whereas here x = √(KaC) = 10⁻³ M, about 1% of the acid.' },
  { id: 'aek-013', topic: 'aek', skill: 'acids/strong-weak', q: 'Ka of HF is 6.8×10⁻⁴. Kb of F⁻ = ?', opts: ['6.8×10⁻⁴', '1.5×10⁻¹¹', '6.8×10⁻¹⁸', '1.5×10⁻⁴'], a: 1, why: 'Kb = Kw/Ka = 10⁻¹⁴/6.8×10⁻⁴ ≈ 1.5×10⁻¹¹. Conjugates multiply to Kw.' },
  { id: 'aek-014', topic: 'aek', skill: 'acids/strong-weak', q: 'Which 0.1 M salt solution is basic?', opts: ['NaF', 'NH₄Cl', 'NaCl', 'NaNO₃'], a: 0, why: 'F⁻ is the conjugate base of a WEAK acid (HF) → hydrolyzes: F⁻ + H₂O ⇌ HF + OH⁻. Cl⁻/NO₃⁻ are neutral spectators; NH₄⁺ is acidic.' },
  { id: 'aek-015', tier: 3, topic: 'aek', skill: 'redox/nernst', q: 'A battery is "dead" when…', opts: ['E° = 0', 'Q = 1', 'the anode dissolves fully', 'Q = K (so E = 0)'], a: 3, why: 'The cell drives toward equilibrium; at Q = K the Nernst equation gives E = 0 — no more push, even with reactants left.', misconception: 'E° is a fixed property of the cell chemistry and does not drain away with use — a dead battery still has exactly the E° it started with. What has fallen to zero is the actual E, because Q has climbed to K. "Dead" therefore means "at equilibrium", not "out of reactants": there is usually plenty of reactant left.' },
  { id: 'aek-016', topic: 'aek', skill: 'redox/electrolysis', q: 'Electrolysis of aqueous NaCl: the product at the CATHODE is…', opts: ['Na metal', 'Cl₂ gas', 'H₂ gas', 'O₂ gas'], a: 2, why: 'Water (−0.83 V) is far easier to reduce than Na⁺ (−2.71 V) → H₂ + OH⁻. Molten NaCl is how you get sodium metal.', misconception: 'What is reduced at a cathode is whatever is <em>easiest</em> to reduce, and in aqueous solution that is often water, not the cation on the label. Electrolysing aqueous NaCl gives H₂, not sodium, because reducing water (−0.83 V) is far easier than reducing Na⁺ (−2.71 V). Sodium metal requires <em>molten</em> NaCl, where no water is present to be reduced first.' },
  { id: 'aek-017', topic: 'aek', skill: 'redox/electrolysis', q: 'Charge needed to plate 0.10 mol of Ag from Ag⁺?', opts: ['96485 C', '9650 C', '4825 C', '19300 C'], a: 1, why: 'n = 1 e⁻ per Ag: Q = 0.10 × 96485 ≈ 9650 C (≈ 2.7 A·h).' },
  { id: 'aek-018', topic: 'aek', skill: 'kinetics/rate-laws', q: 'Doubling [A] quadruples the initial rate. Order in A?', opts: ['2', '1', '0', '3'], a: 0, why: 'rate ∝ [A]ⁿ: 2ⁿ = 4 → n = 2. Method of initial rates in one line.' },
  { id: 'aek-019', topic: 'aek', skill: 'kinetics/catalysis', q: 'A catalyst speeds a reaction by…', opts: ['raising the temperature', 'increasing collision frequency', 'shifting the equilibrium right', 'lowering Ea for forward AND reverse'], a: 3, why: 'A new pathway with lower barrier — both directions accelerate equally, so K and ΔG° are untouched.', misconception: 'A catalyst changes the <em>time</em> to reach equilibrium, never the <em>yield</em> at equilibrium. Because it lowers the barrier equally in both directions, kf and kr rise by the same factor and K = kf/kr is unchanged — as is ΔG°, which is fixed by the reactants and products alone and knows nothing about the path between them.' },
  { id: 'aek-020', topic: 'aek', skill: 'kinetics/integrated-rate', q: 'For a SECOND-order reaction, the half-life…', opts: ['is constant', 'is zero', 'gets shorter as it proceeds', 'gets longer as the reaction proceeds'], a: 3, why: 't½ = 1/(k[A]₀): as [A] falls, each successive half-life doubles — the long tail of 2nd-order decays.', misconception: 'A constant half-life is a property of first-order kinetics alone, not of decay in general. For a second-order reaction t½ = 1/(k[A]₀), so every successive half-life is twice as long as the last, and the reaction develops a very long tail. If a question gives you a half-life and expects it to be constant, it has told you the order — and if the half-life is drifting, that is your evidence the reaction is not first order.' },
  { id: 'aek-021', tier: 3, topic: 'aek', skill: 'acids/polyprotic', q: 'In the titration of H₂CO₃ (diprotic) with NaOH, the pH at the FIRST half-equivalence equals…', opts: ['pKa1', 'pKa2', '(pKa1+pKa2)/2', '7'], a: 0, why: 'The first buffer region is H₂CO₃/HCO₃⁻ → pH = pKa1 (6.35). Midway between the two equivalence points pH ≈ (pKa1+pKa2)/2.', misconception: 'Each proton of a diprotic acid has its own half-equivalence AND its own equivalence point, and the two are easily slid into one another. The first half-equivalence sits in the H₂CO₃/HCO₃⁻ buffer, so pH = pKa1; the average (pKa1 + pKa2)/2 belongs to the first EQUIVALENCE point, where amphiprotic HCO₃⁻ is the only species present. Picking the average means shifting one step along the curve.' },
  { id: 'aek-022', tier: 3, topic: 'aek', skill: ['acids/indicators', 'acids/titration-curves'], q: 'The best indicator for a titration has pKind close to…', opts: ['7 always', 'the pH at the equivalence point', 'the pKa of the analyte acid', '0'], a: 1, why: 'The indicator flips within pKind ± 1 — that window must straddle the steep jump at equivalence (8.7 for weak acid/strong base → phenolphthalein).', misconception: 'The indicator must flip where the curve is STEEP, which is the equivalence point — not pH 7, and not the analyte\'s pKa, which marks half-equivalence in the flattest part of the buffer region. Only strong acid with strong base has its equivalence at 7; a weak acid titrated with strong base leaves a basic salt and jumps through about 8.7, which is why phenolphthalein works there and methyl orange does not.' },
  { id: 'aek-023', topic: 'aek', skill: 'redox/cell-potential', q: 'The strongest OXIDIZING agent here is…', opts: ['Li⁺ (E° = −3.04 V)', 'Zn²⁺ (−0.76 V)', 'F₂ (+2.87 V)', 'Cu²⁺ (+0.34 V)'], a: 2, why: 'Most positive reduction potential = most eager to be reduced = strongest oxidizer. (Li METAL is the strongest reducer — flip sides!)', misconception: 'A standard reduction potential table ranks oxidising strength <em>as written</em> — as reductions. The most positive E° is the best oxidising agent (F₂ at +2.87 V), and the most negative marks the best reducing agent, but that reducing agent is the <em>metal</em> on the right-hand side, not the ion on the left. Li⁺ is a terrible oxidiser; Li metal is a superb reducer. Read which side of the half-equation the species you are asked about is on.' },
  { id: 'aek-024', topic: 'aek', skill: 'kinetics/mechanisms', q: 'A species produced in one mechanism step and consumed in a later one is a(n)…', opts: ['catalyst', 'activated complex', 'inhibitor', 'intermediate'], a: 3, why: 'Intermediates appear AFTER they\'re made and vanish; catalysts enter FIRST and are regenerated. Neither may appear in the overall equation.' },
  { id: 'aek-025', topic: 'aek', skill: 'kinetics/arrhenius', q: 'ln k vs 1/T is a straight line with slope equal to…', opts: ['−Ea/R', 'Ea', '−Ea', 'A (frequency factor)'], a: 0, why: 'Arrhenius linearized: ln k = ln A − (Ea/R)(1/T). Steeper slope = bigger Ea = more temperature-sensitive.' },
  // ---- flagship additions: redox and kinetics ----
  { id: 'aek-026', tier: 3, topic: 'aek', skill: 'redox/cell-potential', q: 'Given Fe³⁺ + 3e⁻ → Fe(s), E° = −0.036 V and Fe²⁺ + 2e⁻ → Fe(s), E° = −0.447 V, what is E° for Fe³⁺ + e⁻ → Fe²⁺?', opts: ['+0.411 V', '+0.786 V', '−0.483 V', '+0.262 V'], a: 1, why: 'Potentials are not additive — free energies are. ΔG°₁ = −3F(−0.036) = +0.108F and ΔG°₂ = −2F(−0.447) = +0.894F. The target half-reaction is reaction 1 minus reaction 2, so ΔG° = 0.108F − 0.894F = −0.786F. It transfers n = 1 electron, so E° = −ΔG°/(1·F) = +0.786 V. In one line: E° = (3E°₁ − 2E°₂)/1 = −0.108 + 0.894 = +0.786 V. That sits close to the tabulated +0.771 V for Fe³⁺/Fe²⁺; the gap is the rounding carried by the −0.036 V value.', misconception: 'The rule "just subtract the potentials" belongs to a different calculation than the one asked here. It works for a <b>full cell</b> (E°cell = E°cathode − E°anode) for one reason only: the electrons cancel, so the two n values are equal and drop out of the ΔG bookkeeping. Building a <b>new half-reaction</b> out of two others leaves electrons uncancelled — 3e⁻ − 2e⁻ = 1e⁻ — so the n values do not match and the potentials cannot be subtracted. Whenever the electron counts differ, convert to ΔG = −nFE°, do the arithmetic there, and convert back with the n of the reaction you actually built.' },
  { id: 'aek-027', tier: 3, topic: 'aek', skill: 'redox/nernst', q: 'A concentration cell is assembled at 25 °C: Cu(s) | Cu²⁺ (0.0010 M) ‖ Cu²⁺ (0.100 M) | Cu(s). What is E, and which compartment is the anode?', opts: ['+0.0296 V, with the 0.0010 M compartment as the anode', '+0.0592 V, with the 0.100 M compartment as the anode', '+0.0592 V, with the 0.0010 M compartment as the anode', '0 V — both electrodes are copper, so E° = 0 and no current flows'], a: 2, why: 'Both half-cells are the same couple, so E° = 0 exactly and the whole potential is the Nernst term: E = (0.0592/n)·log([Cu²⁺]cathode/[Cu²⁺]anode) with n = 2. That gives E = 0.0296 × log(0.100/0.0010) = 0.0296 × log(100) = 0.0296 × 2 = +0.0592 V. The direction is set by what makes ΔG negative: the cell runs so as to even the two concentrations out, so Cu²⁺ is plated out of the concentrated side (that is the cathode) and copper dissolves into the dilute side (the anode).', misconception: 'The trap is importing the intuition of diffusion — "stuff moves from concentrated to dilute, so the concentrated side must be the one giving things up". A galvanic cell is not transport down a gradient; it is a reaction whose spontaneous direction is fixed by Q < K. Here K = 1 (identical chemistry on both sides), so spontaneity requires Q = [dilute]/[concentrated] < 1 for the reaction as written, and the reaction as written must therefore CONSUME the concentrated ion. Consuming Cu²⁺ is reduction, and reduction defines the cathode — so the concentrated compartment is the cathode and the dilute one is the anode. The net effect still evens the concentrations out, which is the grain of truth the intuition was reaching for.' },
  { id: 'aek-028', tier: 3, topic: 'aek', skill: 'redox/electrolysis', q: '250 mL of a solution 0.50 M in Cu²⁺ and 0.50 M in Zn²⁺ is electrolysed between inert electrodes at 1.93 A for 25.0 min. E°(Cu²⁺/Cu) = +0.34 V, E°(Zn²⁺/Zn) = −0.76 V; Cu = 63.55, Zn = 65.38 g/mol. What is deposited at the cathode?', opts: ['0.95 g of copper', '0.98 g of zinc', '0.97 g of a copper–zinc mixture', '1.91 g of copper'], a: 0, why: 'Charge first: Q = It = 1.93 × (25.0 × 60) = 2895 C, so n(e⁻) = 2895/96485 = 0.0300 mol. Cu²⁺ is the easier ion to reduce (+0.34 V versus −0.76 V), and each Cu needs two electrons, so n(Cu) = 0.0150 mol → m = 0.0150 × 63.55 = 0.953 g. The solution holds 0.250 × 0.50 = 0.125 mol Cu²⁺, so only 12% of it is consumed and copper is still plentiful when the current stops — zinc never gets a turn. (Using one electron per copper gives 1.91 g; plating zinc instead gives 0.98 g; sharing the charge equally between the two metals gives 0.97 g.)', misconception: 'The wrong picture is of electrolysis as a bulk extraction that pulls out whatever is in the beaker in proportion to how much of it is there. What actually happens is a competition decided by potential: the cathode sits at whatever potential the supply forces on it, and the ion that is easiest to reduce takes essentially all the current until it is nearly gone. Nernst puts a number on "nearly": co-deposition of zinc would need E(Cu²⁺/Cu) to have fallen to E(Zn²⁺/Zn) ≈ −0.77 V, which requires [Cu²⁺] ≈ 10⁻³⁸ M. Deposition from a mixture is sequential, not simultaneous, and that is exactly why electrolysis is a purification technique.' },
  { id: 'aek-029', tier: 3, topic: 'aek', skill: ['redox/cell-potential', 'redox/nernst'], q: 'For copper, Cu²⁺ + e⁻ → Cu⁺ has E° = +0.153 V and Cu⁺ + e⁻ → Cu(s) has E° = +0.521 V. What is K at 25 °C for the disproportionation 2Cu⁺ → Cu²⁺ + Cu(s)?', opts: ['6.1×10⁻⁷', '1.6×10⁶', '2.7×10¹²', '2.4×10¹¹'], a: 1, why: 'Cu⁺ plays both parts: it is oxidised (Cu⁺ → Cu²⁺ + e⁻, the +0.153 V couple run backwards) and reduced (Cu⁺ + e⁻ → Cu, +0.521 V). So E°cell = E°cathode − E°anode = 0.521 − 0.153 = +0.368 V — positive, so the disproportionation is spontaneous under standard conditions. Exactly one electron moves per equation as written, so n = 1: log K = nE°/0.0592 = 0.368/0.0592 = 6.22, giving K = 1.6×10⁶. This is why Cu⁺ salts do not survive in water unless the ion is locked up as an insoluble solid (CuCl) or a complex.', misconception: 'The "2" in 2Cu⁺ is a stoichiometric coefficient, not an electron count, and reading n off it is the standard way to get this wrong. n is the number of electrons that actually pass from the reducing agent to the oxidising agent in the equation as balanced — and in a disproportionation one Cu⁺ hands a single electron to the other Cu⁺, so n = 1 even though two ions are consumed. Because n multiplies log K, taking n = 2 does not shift the answer a little: it SQUARES it, turning 10⁶ into 10¹². The safe check is to write the two half-equations and count the electrons that cancel between them.' },
  { id: 'aek-030', tier: 3, topic: 'aek', skill: 'redox/balancing', q: 'In basic solution MnO₄⁻ oxidises I⁻ to IO₃⁻ and is itself reduced to MnO₂(s). In the balanced equation with the smallest whole-number coefficients, OH⁻ appears…', opts: ['as 6 OH⁻ on the left', 'as 8 OH⁻ on the right', 'as 2 OH⁻ on the right', 'as 2 OH⁻ on the left'], a: 2, why: 'The two half-equations in base are MnO₄⁻ + 2H₂O + 3e⁻ → MnO₂ + 4OH⁻ (Mn goes +7 → +4, three electrons) and I⁻ + 6OH⁻ → IO₃⁻ + 3H₂O + 6e⁻ (I goes −1 → +5, six electrons). Doubling the first to match six electrons gives 2MnO₄⁻ + 4H₂O + 6e⁻ → 2MnO₂ + 8OH⁻. Adding the two: 2MnO₄⁻ + I⁻ + 4H₂O + 6OH⁻ → 2MnO₂ + IO₃⁻ + 3H₂O + 8OH⁻. Now cancel the species standing on both sides — 6 of the 8 OH⁻ and 3 of the 4 H₂O — leaving 2MnO₄⁻ + I⁻ + H₂O → 2MnO₂ + IO₃⁻ + 2OH⁻. Check it: charge is −3 on each side, O is 8+1 = 9 left and 4+3+2 = 9 right, H is 2 on each side.', misconception: 'Adding two half-equations is not the last step; cancelling is. The 8 OH⁻ on the right is what you get by stopping one line early, with 6 OH⁻ still sitting on the left where the iodide half-equation put them — an equation that is arithmetically balanced but not in lowest terms, and therefore not the answer to "smallest whole-number coefficients". The related belief worth dropping is that a basic-solution equation must show OH⁻ as a reactant because the solution is basic. OH⁻ can end up on either side or vanish entirely; which side it lands on is decided by the water and hydroxide bookkeeping of the two halves, not by the pH of the beaker.' },
  { id: 'aek-031', tier: 3, topic: 'aek', skill: 'kinetics/mechanisms', q: 'The gas-phase reaction 2NO + Br₂ → 2NOBr is proposed to proceed by a fast pre-equilibrium NO + Br₂ ⇌ NOBr₂ (K₁) followed by a slow step NOBr₂ + NO → 2NOBr (k₂). What rate law does this predict, and what happens to the rate if [NO] and [Br₂] are both halved?', opts: ['rate = k[NO][Br₂]; halving both cuts the rate to one quarter', 'rate = k[NOBr₂][NO]; halving both cuts the rate to one quarter', 'rate = k[NO]²[Br₂]; halving both cuts the rate to one sixth', 'rate = k[NO]²[Br₂]; halving both cuts the rate to one eighth'], a: 3, why: 'The slow step sets the rate: rate = k₂[NOBr₂][NO]. But NOBr₂ is an intermediate, so it has to be eliminated using the step held at equilibrium: K₁ = [NOBr₂]/([NO][Br₂]), hence [NOBr₂] = K₁[NO][Br₂]. Substituting gives rate = k₂K₁[NO]²[Br₂] — second order in NO, first order in Br₂, third order overall. Halving both concentrations then multiplies the rate by (½)² × (½) = 1/8. Orders combine multiplicatively, so the overall order of 3 does not mean "divide by 2 × 3 = 6".', misconception: 'The half-remembered rule is "the rate law is the slow step", and it is true only as a starting point. A rate law is a statement about quantities the experimenter can set and measure, and an intermediate is neither: NOBr₂ is created and destroyed inside the mechanism, its concentration is never something you weigh into the flask, and it is pinned by the earlier step at K₁[NO][Br₂]. So the slow step gives you the FORM of the rate law, and every intermediate in it must then be substituted out using the fast equilibria before the expression means anything experimentally. If a proposed rate law contains a species that appears in no beaker, the derivation is unfinished.' },
  { id: 'aek-032', tier: 3, topic: 'aek', skill: ['kinetics/mechanisms', 'kinetics/rate-laws'], q: 'Ozone decomposes, 2O₃ → 3O₂, by O₃ ⇌ O₂ + O (k₁ forward, k₋₁ reverse) then O + O₃ → 2O₂ (k₂). Applying the steady-state approximation to the O atom, what rate law follows when the reverse of the first step is much faster than the second step?', opts: ['rate = k[O₃]² — second order in ozone, with O₂ having no effect', 'rate = k[O₃]²/[O₂] — second order in ozone and inhibited by O₂', 'rate = k[O₃] — first order, because the slow step consumes one O₃', 'rate = k[O₃]²[O₂] — second order in ozone and accelerated by O₂'], a: 1, why: 'Steady state on the oxygen atom means its production equals its consumption: k₁[O₃] = k₋₁[O₂][O] + k₂[O][O₃], so [O] = k₁[O₃]/(k₋₁[O₂] + k₂[O₃]). Ozone disappears in the second step (and net in the first), and substituting gives −d[O₃]/dt = 2k₁k₂[O₃]²/(k₋₁[O₂] + k₂[O₃]). The stated condition k₋₁[O₂] ≫ k₂[O₃] deletes the second term of the denominator: rate = (2k₁k₂/k₋₁)[O₃]²[O₂]⁻¹. The orders are 2 in O₃ and −1 in O₂, so 1 overall, and adding O₂ SLOWS the decomposition — which is what is measured.', misconception: 'The belief doing the damage is that only reactants may appear in a rate law, so a product cannot possibly be in there. Nothing forbids it. A negative order is the fingerprint of a reversible step sitting in front of the rate-determining one: extra O₂ drives O₃ ⇌ O₂ + O backwards, starves the mechanism of oxygen atoms, and slows the whole thing down. If products were truly barred from rate laws, product inhibition — which is ordinary in enzyme kinetics, in polymerisation and here in the stratosphere — could not exist. The rate law is whatever the experiment says it is; the mechanism then has to reproduce it.' },
  { id: 'aek-033', tier: 3, topic: 'aek', skill: 'kinetics/integrated-rate', q: 'For A → products, [A] falls from 0.80 M to 0.40 M in 40 s, and then from 0.40 M to 0.20 M in a further 80 s. How long after the start does [A] reach 0.10 M?', opts: ['120 s', '160 s', '240 s', '280 s'], a: 3, why: 'The half-life DOUBLES as the concentration halves, which is the signature of second order (t½ = 1/(k[A]₀)); first order would repeat 40 s and zero order would halve to 20 s. Take k from the first half-life: k = 1/(t½[A]₀) = 1/(40 × 0.80) = 0.03125 M⁻¹ s⁻¹, and check it against the second: 1/(0.03125 × 0.40) = 80 s, as observed. Now the integrated second-order law, 1/[A] − 1/[A]₀ = kt: 1/0.10 − 1/0.80 = 10.0 − 1.25 = 8.75 M⁻¹, so t = 8.75/0.03125 = 280 s. Counting half-lives gives the same thing, since the third one lasts 160 s: 40 + 80 + 160 = 280 s.', misconception: 'Treating "the half-life" as a fixed property of a reaction is a first-order habit smuggled into a question that has already told you the reaction is not first order. Only for first order is t½ independent of concentration; for second order t½ = 1/(k[A]₀) grows as A is used up, and for zero order t½ = [A]₀/2k shrinks. That makes the pattern of successive half-lives a free order determination before any graph is plotted: constant means first order, doubling means second, halving means zero. Here the data hand you 40 s then 80 s, so multiplying the first half-life by three was ruled out by the second measurement.' },
  { id: 'aek-034', tier: 3, topic: 'aek', skill: ['kinetics/arrhenius', 'kinetics/catalysis'], q: 'A reaction has k = 2.0×10⁻³ s⁻¹ at 300 K and k = 1.4×10⁻² s⁻¹ at 320 K. A catalyst is then found that lowers the activation energy by 40% while leaving the pre-exponential factor unchanged. By what factor does it raise k at 300 K?', opts: ['1.7', '7.0', '2.6×10⁵', '1.3×10⁸'], a: 2, why: 'Get Ea from the two-point Arrhenius equation, ln(k₂/k₁) = −(Ea/R)(1/T₂ − 1/T₁). Here ln(1.4×10⁻²/2.0×10⁻³) = ln 7.00 = 1.946 and 1/300 − 1/320 = 2.083×10⁻⁴ K⁻¹, so Ea = (8.314 × 1.946)/(2.083×10⁻⁴) = 7.77×10⁴ J/mol = 77.7 kJ/mol. The catalyst removes 40% of it: ΔEa = 0.400 × 77.7 = 31.1 kJ/mol, leaving a barrier of 46.6 kJ/mol. With A and T unchanged the two rate constants differ only in the exponential, so k(cat)/k = exp(ΔEa/RT) = exp(31060/(8.314 × 300)) = exp(12.45) = 2.6×10⁵.', misconception: 'The slip is feeding the catalysed barrier itself into the exponential — exp(46600/RT) = 1.3×10⁸ — instead of the amount by which the barrier fell. exp(−Ea/RT) is not a rate constant; it is the fraction of collisions with enough energy, and it only becomes k once multiplied by A. When you take a RATIO of two rate constants that share the same A, the pre-exponential factors cancel and the exponentials combine: k(cat)/k = exp(−Ea,cat/RT)/exp(−Ea/RT) = exp[(Ea − Ea,cat)/RT]. Only the DIFFERENCE of the barriers survives, which is also why a catalyst quoted as "lowering Ea by 25 kJ/mol" gives a definite speed-up without anyone needing to know the original height.' },
  { id: 'aek-035', tier: 3, topic: 'aek', skill: ['kinetics/rate-laws', 'kinetics/mechanisms'], q: 'A gas-phase isomerisation A → B is cleanly first order in A at 1 atm, but below 1 torr the same reaction is second order in A. Its accepted mechanism is A + A ⇌ A* + A (k₁, k₋₁) followed by A* → B (k₂). Which statement is correct?', opts: ['The molecularity of the reaction rises from 1 to 2 as the pressure falls, and the order follows it', 'Below 1 torr the activating collision becomes rate-limiting, so the ORDER changes while each step keeps its molecularity', 'Below 1 torr the reaction stops being elementary, so its rate law is no longer given by its stoichiometry', 'At 1 atm ordinary A is in vast excess over A*, so the first order is a pseudo-order hiding a bimolecular reaction'], a: 1, why: 'Steady state on A*: k₁[A]² = k₋₁[A][A*] + k₂[A*], so [A*] = k₁[A]²/(k₋₁[A] + k₂) and rate = k₂[A*] = k₁k₂[A]²/(k₋₁[A] + k₂). At high pressure collisions are frequent, k₋₁[A] ≫ k₂, and one power of [A] cancels: rate = (k₁k₂/k₋₁)[A], first order. At low pressure k₂ ≫ k₋₁[A], the denominator is just k₂, and rate = k₁[A]² — second order, because now almost every energised molecule reacts and it is the collision that is the bottleneck. The mechanism is unchanged throughout: the same two steps, of molecularity 2 and 1, merely trade places as the slow one.', misconception: 'Behind the wrong answer is the idea that order and molecularity are two names for one quantity, so an order that changed must mean a molecularity that changed. They are different kinds of thing. Molecularity counts the species entering the transition state of one ELEMENTARY step in a proposed mechanism: a small fixed integer, part of a model, never measured. Order is the exponent extracted from experiment for the OVERALL reaction, and it is free to be fractional, negative, or dependent on pressure and concentration. They agree only when the reaction really is a single elementary step. Here the observation is not that a molecule learned to react with a partner it did not have before — it is that which step limits the rate depends on how often molecules meet.' },
];

export const GASES_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'gas-001', topic: 'gases', skill: 'states/gas-laws', q: 'STP temperature is…', opts: ['0 °C', '25 °C', '100 °C', '−273 °C'], a: 0, why: 'This is asking for the temperature part of standard temperature and pressure. STP is defined as 0 °C, which is 273.15 K, at a pressure of 1 bar. The 25 °C you may have seen belongs to standard state, a different convention used for thermodynamic data.' },
  { id: 'gas-002', topic: 'gases', skill: 'states/gas-laws', q: 'At constant T, halving the volume of a gas makes the pressure…', opts: ['half', 'double', 'unchanged', 'quadruple'], a: 1, why: 'This is asking what halving the volume does to the pressure. At a fixed temperature the product of pressure and volume stays constant, P × V = constant. Halving V must therefore double P to keep that product the same.' },
  { id: 'gas-003', topic: 'gases', skill: 'states/kmt', q: 'Absolute zero is…', opts: ['0.0 °C', '−100 °C', '−273.15 °C', '−373 °C'], a: 2, why: 'This is asking where the Kelvin scale starts. Absolute zero, 0 K, is the lowest temperature there is, where particle motion is at its minimum. On the Celsius scale that point is −273.15 °C.' },
  { id: 'gas-004', topic: 'gases', skill: 'states/kmt', q: 'Kinetic molecular theory assumes gas particles…', opts: ['attract one another strongly', 'all travel at the very same speed', 'move slowly and steadily', 'have no volume and no attractions'], a: 3, why: 'This is asking what the kinetic molecular theory assumes about gas particles. The model treats particles as points with no volume of their own and no attraction between them. Their collisions are perfectly elastic, losing no energy. Those assumptions are why real gases stray from the model at high pressure and low temperature.', misconception: 'The kinetic model does not assume all particles move at the same speed — it assumes the <em>opposite</em>, and that is the whole point of the Maxwell–Boltzmann distribution. At any instant the sample contains a huge spread of speeds, and temperature fixes the shape of that spread rather than a single value. The real assumptions are point-like particles, no intermolecular forces and perfectly elastic collisions, all three of which fail at high pressure and low temperature.' },
  { id: 'gas-005', topic: 'gases', skill: 'states/imf', q: 'The strongest intermolecular force in liquid water is…', opts: ['hydrogen bonds', 'permanent dipole–dipole', 'London dispersion forces', 'ionic attraction'], a: 0, why: 'This is asking which attraction between water molecules is strongest. A hydrogen bond forms when an H attached to N, O or F is drawn to a lone pair on a neighbouring molecule. Each water molecule has two O–H bonds and two lone pairs, so it can make up to four.' },
  // ---- olympiad ----
  { id: 'gas-006', topic: 'gases', skill: 'states/kmt', q: 'He effuses how many times faster than CH₄ (M = 16)?', opts: ['4×', '2×', '√2×', '16×'], a: 1, why: 'Graham: rate ∝ 1/√M → √(16/4) = 2.' },
  { id: 'gas-007', topic: 'gases', skill: 'states/real-gases', q: 'A real gas behaves most ideally at…', opts: ['low T, high P', 'low T, low P', 'high T, low P', 'high T, high P'], a: 2, why: 'Kinetic energy swamps attractions (high T); molecular volume is negligible (low P).', misconception: 'Ideality is favoured by high temperature and LOW pressure, which is the opposite of the intuitive answer. High pressure pushes molecules close enough that their own volume matters (the b term), and low temperature lets attractions bite (the a term). "High T, high P" gets half the reasoning right and the other half exactly backwards.' },
  { id: 'gas-008', topic: 'gases', skill: 'states/imf', q: 'Which noble gas has the highest boiling point?', opts: ['He', 'Ne', 'Ar', 'Xe'], a: 3, why: 'Dispersion forces grow with polarizability (electron count): Xe 165 K ≫ He 4 K.' },
  { id: 'gas-009', topic: 'gases', skill: 'states/gas-laws', q: 'H₂ collected over water at 25 °C, total P = 770 torr, P°(H₂O) = 24 torr. P(H₂) = ?', opts: ['746 torr', '794 torr', '770 torr', '386 torr'], a: 0, why: 'Dalton: subtract the water vapor. 770 − 24 = 746 torr — skip this and your mole count is inflated.' },
  { id: 'gas-010', topic: 'gases', skill: 'states/phase-behaviour', q: 'Water\'s solid–liquid line slopes LEFT (negative). Therefore…', opts: ['ice sublimes easily', 'water can\'t freeze under pressure', 'pressure melts ice', 'ice is denser than water'], a: 2, why: 'Compressing at constant T crosses solid → liquid because ice is LESS dense. Nearly unique to water.', misconception: 'Water\'s solid–liquid line slopes backwards because ice is <em>less</em> dense than liquid water — nearly every other substance slopes the normal way. That negative slope means increasing the pressure at constant temperature melts ice rather than freezing water. Assuming solid is always denser than liquid works for almost everything and fails for exactly the substance every exam asks about.' },
  { id: 'gas-011', topic: 'gases', skill: 'states/gas-laws', q: 'Density of CO₂ (M = 44) at 0 °C and 1 atm ≈ ?', opts: ['1.00 g/L', '1.96 g/L', '0.5 g/L', '44 g/L'], a: 1, why: 'd = PM/RT = M/22.4 ≈ 1.96 g/L — heavier than air (29 g/mol effective), which is why CO₂ pools low.' },
  { id: 'gas-012', topic: 'gases', skill: 'states/kmt', q: 'To DOUBLE the rms speed of a gas sample, its Kelvin temperature must…', opts: ['quadruple', 'double', 'increase √2×', 'increase 8×'], a: 0, why: 'v(rms) ∝ √T → doubling speed needs 4× the absolute temperature.', misconception: 'Root-mean-square speed goes as √T, not T, so speeds and temperatures do not scale together. Doubling v_rms needs FOUR times the absolute temperature; it is the average kinetic energy (½mv²) that is proportional to T. And the temperature must be in kelvin — doubling 300 °C is meaningless here.' },
  { id: 'gas-013', topic: 'gases', skill: 'states/gas-laws', q: 'A flask holds 1 mol N₂ and 3 mol H₂ at 8 atm total. P(N₂) = ?', opts: ['1 atm', '6 atm', '4 atm', '2 atm'], a: 3, why: 'Mole fraction ¼ × 8 atm = 2 atm. Partial pressure = xᵢ·P(total).' },
  { id: 'gas-014', topic: 'gases', skill: 'states/real-gases', q: 'In van der Waals, a LARGE "a" constant means the gas…', opts: ['has large, bulky molecules', 'is monatomic, like argon', 'has strong attractions', 'behaves almost ideally'], a: 2, why: '"a" corrects pressure for attractions (P is lower than ideal). NH₃ and H₂O have big a; He tiny. "b" is molecular volume.' },
  { id: 'gas-015', topic: 'gases', skill: 'states/phase-behaviour', q: 'Half the liquid in a sealed flask is removed (some liquid remains). The vapor pressure…', opts: ['halves', 'is unchanged', 'doubles', 'drops to zero'], a: 1, why: 'Vapor pressure is an equilibrium property of the LIQUID at that temperature — independent of amounts, as long as liquid is present.', misconception: 'Vapour pressure is a property of the liquid at a given temperature, not of how much liquid there is. Remove half the liquid and the equilibrium simply re-establishes at the same pressure, provided <em>some</em> liquid remains; the same is true if you change the container\'s size. What does change vapour pressure is temperature, and nothing else.' , why2: 'Think of two rates at the surface, not of an amount. Molecules escape the liquid at a rate set by temperature alone (how many have enough energy to break free per unit area per second), and return at a rate proportional to how crowded the vapour is. Vapour pressure is simply where those two rates balance — and neither one knows how deep the liquid underneath is. Remove half the liquid and the headspace grows, so a little more liquid evaporates to refill it, and the pressure settles back to precisely the same value. The only way to change it is to change T (or the liquid). The argument fails at exactly one point: when the last drop evaporates there is no liquid to balance against, and what is left is just a fixed quantity of gas obeying PV = nRT.' },
  { id: 'gas-016', topic: 'gases', skill: 'states/phase-behaviour', q: 'Water boils at ~70 °C on a high mountain because…', opts: ['the atmospheric pressure is lower', 'the air is colder at altitude', 'the water is purer up there', 'weaker gravity lowers water\'s vapour pressure'], a: 0, why: 'Boiling = vapor pressure reaches external pressure. At 0.33 atm that happens at ~71 °C — food cooks slower.' },
  { id: 'gas-017', topic: 'gases', skill: 'states/colligative', q: 'Solvent mole fraction 0.90, pure vapor pressure 100 torr. Solution vapor pressure (Raoult)?', opts: ['100 torr', '81 torr', '10 torr', '90 torr'], a: 3, why: 'P = x(solvent)·P° = 0.90 × 100 = 90 torr — nonvolatile solute dilutes the surface.' },
  { id: 'gas-018', topic: 'gases', skill: 'states/real-gases', q: 'Which gas deviates MOST from ideal behavior?', opts: ['He gas', 'H₂ gas', 'NH₃', 'Ne gas'], a: 2, why: 'NH₃ hydrogen-bonds (big a) and is comparatively large (b). Small nonpolar He/H₂/Ne are the most ideal gases known.' },
  { id: 'gas-019', tier: 3, topic: 'gases', skill: 'states/colligative', q: 'Which freezes at the LOWEST temperature? (aqueous, per kg water)', opts: ['0.10 mol glucose', '0.08 mol CaCl₂', '0.10 mol NaCl', '0.15 mol sucrose'], a: 1, why: 'Count effective particles (i × m): glucose 0.10, NaCl 0.10×2 = 0.20, CaCl₂ 0.08×3 = <b>0.24</b>, sucrose 0.15. Colligative properties only count particles — CaCl₂ wins despite the smallest mole number.', misconception: 'Colligative properties count dissolved <em>particles</em>, not formula units — so the van\'t Hoff factor i has to go in before you compare. 0.08 mol of CaCl₂ releases 0.24 mol of ions and depresses the freezing point more than 0.10 mol of NaCl (0.20) or 0.15 mol of sucrose (0.15), despite having the smallest mole count on the list. Comparing molalities without multiplying by i is the standard error here.' },
  { id: 'gas-020', topic: 'gases', skill: 'equilibrium/le-chatelier', q: 'Warm soda goes flat faster because gas solubility…', opts: ['rises with temperature', 'falls with temperature', 'is pressure-independent', 'depends on the bottle'], a: 1, why: 'Dissolving gas is exothermic → Le Chatelier: heat pushes CO₂ out. (Henry\'s law covers the pressure half of the story.)' },
  { id: 'gas-021', topic: 'gases', skill: 'states/colligative', q: 'In osmosis, solvent flows through the membrane toward the side with…', opts: ['the lower solute concentration', 'the higher temperature side', 'higher solute concentration', 'the lower pressure side'], a: 2, why: 'Toward the more concentrated solution — diluting it. Stopping that flow takes π = iMRT of applied pressure.', misconception: 'Osmosis moves <em>solvent</em> toward the more concentrated solution, which feels backwards until you stop thinking of it as the solute moving. The membrane blocks solute entirely; solvent simply crosses more often in the direction that dilutes, because there is more free solvent on the dilute side. Describing osmosis as "solute flowing to even things out" is the model to discard — that is diffusion, and the membrane forbids it.' },
  { id: 'gas-022', tier: 3, topic: 'gases', skill: 'states/kmt', q: 'An unknown gas takes twice as long as He to effuse. Its molar mass ≈ ?', opts: ['8 g/mol', '32 g/mol', '2 g/mol', '16 g/mol'], a: 3, why: 'time ∝ √M: 2× slower → M = 4 × 2² = 16 g/mol (methane?).', misconception: 'Graham\'s law is about RATES, and time is the reciprocal of rate — twice as long means half as fast, so √(M/4) = 2 and M = 16. Multiplying the molar mass by the time ratio without squaring gives 8; forgetting to invert, and reading "twice as long" as twice as fast, sends the unknown lighter than helium instead of heavier.' },
  { id: 'gas-023', topic: 'gases', skill: 'states/phase-behaviour', q: 'Above the critical point, a substance is…', opts: ['a supercritical fluid', 'a superheated liquid phase', 'an ionised plasma', 'invariably a solid'], a: 0, why: 'Beyond Tc, Pc no pressure can condense it — density varies continuously. Supercritical CO₂ extracts caffeine.' },
  { id: 'gas-024', topic: 'gases', skill: 'states/phase-behaviour', q: 'At its triple point, a substance…', opts: ['is on the point of decomposing', 'has three phases at equilibrium', 'boils and freezes in alternation', 'is already supercritical'], a: 1, why: 'One unique (T, P) where solid, liquid, and vapor coexist — water: 0.01 °C, 0.006 atm (used to define the kelvin).' },
  { id: 'gas-025', tier: 3, topic: 'gases', skill: 'states/colligative', q: '6.0 g of an unknown nonelectrolyte in 100 g water freezes at −0.93 °C (Kf = 1.86). Molar mass ≈ ?', opts: ['60 g/mol', '180 g/mol', '120 g/mol', '30 g/mol'], a: 2, why: 'm = 0.93/1.86 = 0.50 mol/kg → 0.050 mol in 0.100 kg → M = 6.0/0.050 = <b>120 g/mol</b>. Colligative properties weigh molecules.', misconception: 'Molality is moles per kilogram of SOLVENT, so 0.50 mol/kg must still be multiplied by the 0.100 kg of water to give 0.050 mol — treating the molality as the number of moles is what shrinks the answer. The other reliable slip is inverting the first step: m = ΔT/Kf, not Kf/ΔT, which would turn 0.50 mol/kg into 2.0 and the molar mass into 30.' },
  { id: 'gas-026', tier: 3, topic: 'gases', skill: 'states/real-gases', q: '1.00 mol CO₂ is held in 0.500 L at 300 K (a = 3.59 L²·atm·mol⁻², b = 0.0427 L·mol⁻¹). The van der Waals pressure is closest to…', opts: ['34.9 atm', '39.5 atm', '49.2 atm', '53.8 atm'], a: 1, why: 'P = RT/(V − b) − a/V². Repulsive term first: RT/(V − b) = (0.08206 × 300)/(0.500 − 0.0427) = 24.62/0.4573 = <b>53.83 atm</b>. Attractive term: a/V² = 3.59/0.500² = 3.59/0.250 = <b>14.36 atm</b>. So P = 53.83 − 14.36 = <b>39.5 atm</b>, against an ideal 0.08206 × 300/0.500 = 49.2 atm. At this density the attraction correction (14.4 atm) outweighs the excluded-volume correction (+4.6 atm), so the real pressure sits <em>below</em> ideal.', misconception: 'The two van der Waals corrections do not both act on the ideal pressure — they act in different places, and 34.9 atm comes from subtracting a/V² straight off RT/V and never shrinking the volume at all. The b term is a correction to the space available (V − b, which raises the pressure), while a/V² is a correction to the wall impact (which lowers it). Treating vdW as "ideal minus attractions" keeps half the equation and silently deletes the half that fights it; here that half is worth 4.6 atm.' },
  { id: 'gas-027', tier: 3, topic: 'gases', skill: 'states/real-gases', q: 'A gas has Z = PVₘ/RT = 0.86 at 100 atm and 250 K. Its molar volume, and what the value of Z tells you, are…', opts: ['0.176 L·mol⁻¹; finite molecular volume dominates', '0.205 L·mol⁻¹; Z only matters above a few hundred atm', '0.176 L·mol⁻¹; attractions dominate', '0.239 L·mol⁻¹; attractions dominate'], a: 2, why: 'Rearrange the definition for the molar volume: Vₘ = ZRT/P = 0.86 × 0.08206 × 250/100 = 0.86 × 0.2051 = <b>0.176 L·mol⁻¹</b> (the ideal value is 0.205 L·mol⁻¹). Z &lt; 1 means the gas is <em>more</em> compressed than ideal, i.e. attractions are pulling the molecules together faster than their own hard-core volume can push them apart — the a term is winning. Push the pressure higher and the excluded volume takes over, Z passes back through 1 and climbs above it.', misconception: 'Z is not a fudge factor multiplying the wrong way: it is defined as PVₘ/RT, so Vₘ = ZRT/P — multiply the ideal molar volume by Z, never divide by it. Dividing gives 0.239 L·mol⁻¹, which is <em>larger</em> than ideal and would mean the gas resists compression, exactly the opposite of what Z &lt; 1 records. The reading to fix is "Z &lt; 1 means less gas fits in"; it means the same gas occupies less room than ideality predicts, which only attractions can do.' },
  { id: 'gas-028', tier: 3, topic: 'gases', skill: 'states/kmt', q: 'Under identical conditions, 0.25 mol of O₂ (M = 32.0) effuses through a pinhole in 60 s; 0.25 mol of an unknown alkane CₙH₂ₙ₊₂ takes 90 s. The alkane is…', opts: ['CH₄', 'C₂H₆', 'C₃H₈', 'C₅H₁₂'], a: 3, why: 'Equal amounts, so rate ∝ 1/time and time ∝ √M. Hence √(M/32.0) = 90/60 = 1.50, giving M = 32.0 × 1.50² = 32.0 × 2.25 = <b>72.0 g·mol⁻¹</b>. Now the second step: CₙH₂ₙ₊₂ with M = 72 needs 12.011n + 1.008(2n + 2) = 72 → 14.03n = 69.98 → n = 4.99, so <b>C₅H₁₂</b> (pentane, 72.15 g·mol⁻¹).', misconception: 'Reading "1.5 times as long" as "1.5 times the molar mass" skips the square root — Graham’s law ties rate to 1/√M, so the mass ratio is the <em>square</em> of the time ratio, 2.25 not 1.50. That slip gives 48 g·mol⁻¹ and points at propane. The other habit worth breaking is reaching for the atomic mass of oxygen: the effusing particle is O₂ at 32.0, not O at 16.0, and using 16.0 halves every molar mass in the problem.' },
  { id: 'gas-029', tier: 3, topic: 'gases', skill: 'states/gas-laws', q: 'A rigid vessel at 400 K holds H₂ at 0.20 atm and O₂ at 0.50 atm. The mixture is sparked and reacts completely. The final total pressure at 400 K is…', opts: ['0.40 atm', '0.50 atm', '0.60 atm', '0.70 atm'], a: 2, why: 'At fixed T and V, partial pressures are stand-ins for moles. 2H₂ + O₂ → 2H₂O: 0.20 atm of H₂ needs 0.10 atm of O₂, and 0.50 atm is available, so H₂ is limiting. Consumed: 0.20 atm H₂ and 0.10 atm O₂; produced: 0.20 atm H₂O. Left over: O₂ 0.50 − 0.10 = 0.40 atm, plus H₂O 0.20 atm. At 400 K water is a <em>vapour</em> (well above 373 K at these pressures), so it counts: P(total) = 0.40 + 0.20 = <b>0.60 atm</b>.', misconception: 'The reflex that "the water drops out of the gas phase" is a habit picked up from room-temperature eudiometry, and at 400 K it is simply false — dropping the 0.20 atm of steam leaves 0.40 atm and loses a third of the answer. Decide whether a product is condensed by comparing the temperature with its boiling point at that pressure, not by remembering that H₂O is "a liquid". The second trap is the unbalanced H₂ + O₂ → H₂O, which consumes O₂ one-for-one and yields 0.50 atm.' },
  { id: 'gas-030', tier: 3, topic: 'gases', skill: 'states/kmt', q: 'At what temperature do O₂ molecules (M = 32.0) have the same root-mean-square speed as H₂ (M = 2.0) at 27 °C?', opts: ['19 K', '1200 K', '4800 K', '75 °C'], a: 2, why: 'v(rms) = √(3RT/M). Setting the two equal, 3RT(O₂)/M(O₂) = 3RT(H₂)/M(H₂), so T(O₂) = T(H₂) × M(O₂)/M(H₂) = 300 K × 32.0/2.0 = 300 × 16 = <b>4800 K</b>. (Sanity check: v(rms) for H₂ at 300 K is √(3 × 8.314 × 300/0.0020) = 1934 m·s⁻¹, and for O₂ at 4800 K, √(3 × 8.314 × 4800/0.0320) = 1934 m·s⁻¹.)', misconception: 'The square root belongs to the whole ratio T/M, so once the speeds are set equal the root disappears and T scales with M <em>linearly</em>. Taking √16 = 4 and answering 1200 K applies the root twice — that would make the O₂ speed only half the hydrogen’s, not equal to it. It is also worth noticing what this number means physically: matching hydrogen’s room-temperature speed demands a temperature no oxygen molecule would survive, which is why light gases escape a planet’s atmosphere and heavy ones do not.' },
  { id: 'gas-031', tier: 3, topic: 'gases', skill: 'states/phase-behaviour', q: 'A liquid has a vapour pressure of 100 torr at 300 K and 400 torr at 340 K. Its ΔH(vap) is closest to…', opts: ['12.8 kJ·mol⁻¹', '29.4 kJ·mol⁻¹', '84.8 kJ·mol⁻¹', '−29.4 kJ·mol⁻¹'], a: 1, why: 'Clausius–Clapeyron: ln(P₂/P₁) = −(ΔH/R)(1/T₂ − 1/T₁) = (ΔH/R)(1/T₁ − 1/T₂). Left side: ln(400/100) = ln 4 = <b>1.386</b>. Bracket: 1/300 − 1/340 = 0.0033333 − 0.0029412 = <b>3.922 × 10⁻⁴ K⁻¹</b>. So ΔH = 1.386 × 8.314/(3.922 × 10⁻⁴) = 11.53/3.922 × 10⁻⁴ = 2.94 × 10⁴ J·mol⁻¹ = <b>+29.4 kJ·mol⁻¹</b>. Positive, as vapourisation must be, and a typical value for a liquid boiling near 350 K (Trouton: 29.4/350 ≈ 84 J·K⁻¹·mol⁻¹).', misconception: 'The logarithm in Clausius–Clapeyron is natural, not base ten, because it comes from integrating dP/P — using log₁₀ 4 = 0.602 instead of ln 4 = 1.386 shrinks every answer by the same factor 2.303 and gives 12.8 kJ·mol⁻¹. If a calculator habit makes that easy to do, keep the conversion in view: log₁₀ is only allowed with a matching 2.303 in the equation. Dropping the logarithm altogether and using the raw ratio 4 gives 84.8 kJ·mol⁻¹.' },
  { id: 'gas-032', tier: 3, topic: 'gases', skill: 'states/colligative', q: 'A 0.0100 mol·kg⁻¹ aqueous MgSO₄ solution freezes at −0.0316 °C (Kf = 1.86 K·kg·mol⁻¹). Which reading is correct?', opts: ['i = 0.59; the salt is associating into large clusters', 'i = 1.70, so 70 % of the formula units are dissociated', 'i = 1.70, so 85 % of the formula units are dissociated', 'i = 2.00; the measured value is experimental error'], a: 1, why: 'ΔT(f) = i·Kf·m → i = ΔT/(Kf·m) = 0.0316/(1.86 × 0.0100) = 0.0316/0.0186 = <b>1.70</b>. Second step: for a salt giving two ions, a fraction α dissociated leaves (1 − α) intact pairs and makes 2α ions, so i = (1 − α) + 2α = <b>1 + α</b>. Hence α = i − 1 = <b>0.70</b>, i.e. 70 % dissociated. The shortfall from 2.00 is real chemistry, not error: Mg²⁺ and SO₄²⁻ are both doubly charged, so ion pairing is strong and 2:2 salts show the largest deviations of any simple electrolyte.', misconception: 'Converting i into a degree of dissociation by dividing — 1.70/2 = 0.85 — assumes i counts a fraction of the maximum particle number, when in fact it counts particles per formula unit starting from a floor of 1. An undissociated formula unit still contributes one particle, which is why the relation is i = 1 + α for a two-ion salt (and i = 1 + 2α for a three-ion one), and why i can never fall below 1 through incomplete dissociation. Below 1 means the opposite process: solute molecules associating, as carboxylic acids do into dimers in benzene.' },
  { id: 'gas-033', tier: 3, topic: 'gases', skill: 'states/real-gases', q: 'A van der Waals gas has second virial coefficient B(T) = b − a/RT. For N₂ (a = 1.39 L²·atm·mol⁻², b = 0.0391 L·mol⁻¹), the Boyle temperature — where B = 0 and the gas is ideal to first order in density — is…', opts: ['2.3 × 10⁻³ K', '4.3 K', '128 K', '433 K'], a: 3, why: 'Set B = 0: b = a/RT(B) → T(B) = a/(Rb). Units must match a, so take R = 0.08206 L·atm·mol⁻¹·K⁻¹: Rb = 0.08206 × 0.0391 = <b>3.209 × 10⁻³</b> L²·atm·mol⁻²·K⁻¹, so T(B) = 1.39/3.209 × 10⁻³ = <b>433 K</b> (measured: 327 K — the right order, since a and b are themselves fitted constants). Below 433 K attractions win and Z dips below 1; above it, excluded volume wins from the start and Z only ever exceeds 1.', misconception: 'R is not one number — it is one <em>quantity</em> with several numerical values, and which one you may use is decided by the units already sitting in the problem. Here a is quoted in L²·atm·mol⁻² and b in L·mol⁻¹, so R must be 0.08206 L·atm·mol⁻¹·K⁻¹; reaching for the more familiar 8.314 J·mol⁻¹·K⁻¹ mixes joules with litre-atmospheres and returns 4.3 K, a hundredfold too small and colder than nitrogen’s boiling point. Check the units of the constants before choosing R, not after.' },
  { id: 'gas-034', tier: 3, topic: 'gases', skill: 'states/phase-behaviour', q: 'Ice melts at 273.15 K with ΔH(fus) = 6.01 kJ·mol⁻¹; the molar volumes are 19.65 cm³ (ice) and 18.00 cm³ (water). By Clapeyron, the pressure increase needed to lower the melting point by 1.0 K is closest to…', opts: ['1.0 × 10⁵ Pa', '1.4 × 10⁴ Pa', '1.2 × 10⁶ Pa', '1.3 × 10⁷ Pa'], a: 3, why: 'Clapeyron: dP/dT = ΔH/(T·ΔV). The volume <em>change</em> on melting is ΔV = 18.00 − 19.65 = −1.65 cm³·mol⁻¹ = <b>−1.65 × 10⁻⁶ m³·mol⁻¹</b> — negative, which is what tilts water’s solid–liquid line backwards. In SI: dP/dT = 6010/(273.15 × (−1.65 × 10⁻⁶)) = 6010/(−4.507 × 10⁻⁴) = <b>−1.33 × 10⁷ Pa·K⁻¹</b>. So ΔT = −1.0 K needs ΔP ≈ <b>1.3 × 10⁷ Pa</b> — about 130 atm for a single degree.', misconception: 'The pressure-melting story told about ice skating quietly assumes a skater can supply the ~10⁷ Pa this calculation demands; the arithmetic says the slope is enormous, so 1 atm (10⁵ Pa) buys under a hundredth of a degree, and skates glide on a frictional meltwater film instead. The arithmetic trap that produces 1.2 × 10⁶ Pa is using a molar volume (18.00 cm³) where Clapeyron wants the <em>difference</em> between two of them: ΔV here is small (1.65 cm³) and negative, and it is precisely its smallness that makes the slope so steep.' },
  { id: 'gas-035', tier: 3, topic: 'gases', skill: 'states/gas-laws', q: '0.800 g of a gas is collected over water in a 0.500 L vessel at 35 °C; the total pressure is 745 torr and P°(H₂O) at 35 °C is 42.2 torr. The gas is most likely…', opts: ['M = 35.8 g·mol⁻¹ → HCl (36.5)', 'M = 39.1 g·mol⁻¹ → Ar (39.9)', 'M = 41.3 g·mol⁻¹ → propene, C₃H₆ (42.1)', 'M = 43.8 g·mol⁻¹ → CO₂ (44.0)'], a: 3, why: 'Dalton first: P(gas) = 745 − 42.2 = 702.8 torr = 702.8/760 = <b>0.9247 atm</b>. Then n = PV/RT = 0.9247 × 0.500/(0.08206 × 308.15) = 0.4624/25.29 = <b>0.01829 mol</b>. So M = 0.800/0.01829 = <b>43.8 g·mol⁻¹</b>, which within the precision of the measurement is CO₂ (44.0).', misconception: 'A gas collected over water is a <em>mixture</em>: the vessel is saturated with water vapour, so the measured total pressure overstates the sample’s own partial pressure and every mole count built on it comes out too high — here 41.3 g·mol⁻¹ instead of 43.8, an error that grows with temperature because P°(H₂O) roughly doubles every 10 °C. The subtraction is 42.2 torr off, never on; adding it gives 39.1. And 22.4 L·mol⁻¹ is not a universal constant — it is the molar volume at STP only, and using it here (35.8 g·mol⁻¹) ignores both the 35 °C and the missing water correction.' },
];

export const NUCLEAR_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'nuc-001', topic: 'nuclear', skill: 'descriptive/nuclear', q: 'An alpha particle is…', opts: ['a fast-moving electron', 'a free neutron', 'a high-energy photon', 'a helium nucleus'], a: 3, why: 'This is asking what an alpha particle is made of. An alpha particle is a helium nucleus, two protons and two neutrons, with a charge of 2+. Being heavy and charged, it is stopped by a sheet of paper.' },
  { id: 'nuc-002', topic: 'nuclear', skill: 'descriptive/nuclear', q: '100 g of isotope, one half-life passes. Remaining?', opts: ['0 g', '25 g', '50 g', '75 g'], a: 2, why: 'This is asking how much is left after one half-life. A half-life is the time it takes for half the sample to decay. Half of the 100 g decays, so 100 ÷ 2 = 50 g remains.' },
  { id: 'nuc-003', topic: 'nuclear', skill: 'descriptive/nuclear', q: 'Most penetrating radiation?', opts: ['alpha', 'gamma', 'beta', 'all equal'], a: 1, why: 'This is asking which radiation passes through the most material. Gamma rays are high-energy photons with no charge and no mass, so very little stops them. Thick lead or concrete is needed, while alpha stops at paper and beta at thin aluminium.' },
  { id: 'nuc-004', topic: 'nuclear', skill: 'descriptive/coordination', q: 'A ligand bonds to a metal ion by donating…', opts: ['a lone pair of electrons', 'a proton to the metal', 'a neutron to the nucleus', 'positive charge to the metal'], a: 0, why: 'This is asking what a ligand gives to the metal ion. A ligand is a molecule or ion that donates a lone pair of electrons to a metal. The metal accepts that pair, making a coordinate bond in which both electrons came from the ligand.' },
  { id: 'nuc-005', topic: 'nuclear', skill: 'descriptive/coordination', q: 'Coordination number of Co in [Co(NH₃)₆]³⁺?', opts: ['3', '4', '12', '6'], a: 3, why: 'This is asking for the coordination number of the cobalt ion. The coordination number is how many donor atoms are bonded directly to the metal. Six NH₃ ligands are attached here, so the number is 6 and the shape is octahedral.' },
  // ---- olympiad ----
  { id: 'nuc-006', topic: 'nuclear', skill: 'descriptive/nuclear', q: '²³⁸U undergoes alpha decay. The daughter is…', opts: ['²³⁴Pa (Z=91)', '²³⁸Np (Z=93)', '²³⁴Th (Z=90)', '²³⁶U (Z=92)'], a: 2, why: 'A drops 4 (238→234), Z drops 2 (92→90) → thorium-234.' },
  { id: 'nuc-007', topic: 'nuclear', skill: 'descriptive/nuclear', q: 'After 3 half-lives, percent remaining = ?', opts: ['33%', '12.5%', '25%', '6.25%'], a: 1, why: 'Each half-life halves the amount: (½)³ = 1/8 = 12.5%. Radioactive decay is strictly first-order, so the fraction depends only on the number of half-lives elapsed.', misconception: 'Half-lives do not add to a fraction — they multiply. Three half-lives leave (½)³ = 12.5%, not 3 × 50% = 150% gone or "a third left". The same trap in reverse produces "33%": the number of half-lives is an exponent, never a divisor.' },
  { id: 'nuc-008', tier: 3, topic: 'nuclear', skill: 'descriptive/coordination', q: 'In [Fe(CN)₆]³⁻, iron\'s oxidation state and d-count are…', opts: ['+3, d⁵', '+2, d⁶', '+3, d⁶', '+2, d⁵'], a: 0, why: 'Six CN⁻ = −6, overall −3 → Fe³⁺ = [Ar]3d⁵. Strong-field CN⁻ → low spin, 1 unpaired.', misconception: 'CN⁻ is an anionic ligand, so six of them contribute −6 and an overall −3 forces iron to +3 — defaulting to the more familiar Fe(II) is the first slip. The second is counting d electrons from the atom rather than the ion: Fe³⁺ has no 4s electrons at all, so it is [Ar]3d⁵, and "group 8 so d⁶" quietly keeps an electron that ionisation already removed.' },
  { id: 'nuc-009', topic: 'nuclear', skill: 'descriptive/crystal-field', q: 'Which aqueous ion is COLORLESS?', opts: ['Cu²⁺', 'Ni²⁺', 'Fe³⁺', 'Zn²⁺'], a: 3, why: 'Zn²⁺ is d¹⁰ — full d shell, no d→d transition. Same for d⁰ (Sc³⁺, Ti⁴⁺).', misconception: 'Colour in a transition-metal ion needs a partly filled d subshell for a d–d transition to be possible. Zn²⁺ is d¹⁰ — completely full, no vacancy to promote into — so it is colourless, as are d⁰ ions like Sc³⁺ and Ti⁴⁺. "It is a transition metal, so it must be coloured" fails at both ends of the row.' },
  { id: 'nuc-010', topic: 'nuclear', skill: 'descriptive/coordination', q: 'The chelate effect is driven mainly by…', opts: ['stronger M–N bonds', 'entropy, from freed water', 'solvation enthalpy', 'ligand size'], a: 1, why: 'en displacing two NH₃ increases free-particle count → ΔS > 0. Bond enthalpies are nearly identical.', misconception: 'The chelate effect is overwhelmingly <em>entropic</em>, not a matter of stronger bonds. Ethylenediamine and two ammonias form M–N bonds of essentially identical strength; what differs is that one bidentate ligand displaces two monodentate ones, so the number of free particles in solution rises and ΔS is positive. Attributing the effect to bond strength misses the mechanism and the mark.' },
  { id: 'nuc-011', topic: 'nuclear', skill: 'descriptive/nuclear', q: 'A neutron-rich nucleus (above the belt) most likely decays by…', opts: ['alpha', 'positron emission', 'beta-minus', 'electron capture'], a: 2, why: 'β⁻ turns n → p, moving toward the belt. Proton-rich nuclei go the other way (β⁺/EC).', misconception: 'Beta-minus decay does not throw away a neutron; it <em>converts</em> one into a proton, raising Z by one while A stays put. A nucleus above the band of stability has too many neutrons, so β⁻ is what moves it back toward the band. Proton-rich nuclei do the reverse via β⁺ or electron capture — the position relative to the band, not the mass, tells you which mode to expect.' },
  { id: 'nuc-012', topic: 'nuclear', skill: 'descriptive/nuclear', q: '¹¹C (proton-rich) decays by positron emission to…', opts: ['¹²C', '¹¹N', '¹⁰B', '¹¹B'], a: 3, why: 'β⁺: p → n, Z drops 6 → 5, A stays 11 → boron-11. PET scans run on this decay.' },
  { id: 'nuc-013', topic: 'nuclear', skill: 'descriptive/nuclear', q: 'A bone sample has 25% of its original ¹⁴C (t½ = 5730 y). Age?', opts: ['11,460 y', '5,730 y', '17,190 y', '2,865 y'], a: 0, why: '25% = two half-lives = 11,460 years.' },
  { id: 'nuc-014', topic: 'nuclear', skill: 'descriptive/nuclear', q: 'Energy is released by fusion of light nuclei AND fission of heavy ones because binding energy per nucleon peaks at…', opts: ['helium-4', 'iron-56', 'carbon-12', 'uranium-238'], a: 1, why: 'Fe-56 tops the curve — moving toward it from either side releases energy. Stars die at iron.' },
  { id: 'nuc-015', topic: 'nuclear', skill: 'descriptive/nuclear', q: 'Nuclear decay rates are unaffected by temperature because…', opts: ['nuclei are far too small to heat', 'the decay is zero-order, so the rate never falls off', 'the nucleus ignores chemical energies', 'emitted neutrinos carry the heat away'], a: 2, why: 'Chemical energies are eV-scale; nuclear transitions are MeV-scale (10⁶×). No Arrhenius behavior — t½ is bulletproof.', misconception: 'Nuclear half-lives are unaffected by temperature, and no Arrhenius reasoning applies to them; the one real exception, electron capture, shifts by under a percent between chemical forms of ⁷Be. Chemical processes involve electron-volt energies; nuclear transitions involve millions of electron-volts, so ordinary heating is not even remotely enough to perturb them. This immunity is what makes radiometric dating trustworthy — the clock cannot be sped up by burying, burning or dissolving the sample.' },
  { id: 'nuc-016', topic: 'nuclear', skill: 'descriptive/crystal-field', q: '[CoCl₄]²⁻ is tetrahedral and high spin because…', opts: ['Cl⁻ is a strong-field ligand here', 'tetrahedral fields produce no splitting at all', 'Co²⁺ has a filled d¹⁰ shell', 'Δt is small, so pairing never pays'], a: 3, why: 'Small Δt (fewer ligands, off-axis) < pairing energy in essentially every case → tetrahedral complexes are virtually always high spin.', misconception: 'Tetrahedral complexes are essentially always high spin, whatever the ligand. Only four ligands approach, and they do so <em>between</em> the axes, so the splitting Δt is about 4/9 of the octahedral Δo — smaller than the pairing energy in practically every case. Applying the spectrochemical series to a tetrahedral complex as though it might go low spin is the trap; the series decides Δ, but Δt starts too small for it to matter.' },
  { id: 'nuc-017', tier: 3, topic: 'nuclear', skill: 'descriptive/crystal-field', q: 'Unpaired electrons: [Fe(H₂O)₆]³⁺ vs [Fe(CN)₆]³⁻?', opts: ['5 and 1', '1 and 5', '5 and 5', '0 and 5'], a: 0, why: 'Both d⁵. Weak-field H₂O → high spin (5 unpaired); strong-field CN⁻ → low spin t₂g⁵ (1 unpaired). Measured by magnetism!', misconception: 'The spectrochemical series runs against the intuition that water, being the everyday ligand, must split strongly: H₂O is at the WEAK-field end (high spin, 5 unpaired) and CN⁻ near the strong-field end (low spin t₂g⁵, 1 unpaired). Swapping the two gives exactly the "1 and 5" answer, and the same reversal misassigns high and low spin across the whole d-block.' , why2: 'Both ions are d⁵, so there is only one decision to make: does electron number four go into the upper e<sub>g</sub> set, or pair up in t<sub>2g</sub>? That is a straight cost comparison — the splitting Δ<sub>o</sub> against the pairing energy P. H₂O sits low in the spectrochemical series (Δ<sub>o</sub> &lt; P: cheaper to climb, so the electrons spread out, <b>5 unpaired</b>); CN⁻ sits at the very top (Δ<sub>o</sub> &gt; P: cheaper to pair, so t<sub>2g</sub>⁵, <b>1 unpaired</b>). This is not a bookkeeping convention, it is measured: the magnetic moments come out near 5.9 BM and 2 BM respectively, and the strong-field cyanide complex is the intensely coloured one.' },
  { id: 'nuc-018', tier: 3, topic: 'nuclear', skill: 'descriptive/crystal-field', q: 'A complex looks yellow. It absorbs mainly…', opts: ['yellow light, which it re-emits', 'violet/blue light', 'red light at the far end', 'green, its complement'], a: 1, why: 'You see the COMPLEMENT of what\'s absorbed. Yellow appearance = violet absorbed = large Δ (strong-field ligand).', misconception: 'The colour you see is the <em>complement</em> of the colour absorbed, so a yellow complex is absorbing violet-blue light near 410–430 nm. Reading the observed colour directly as the absorbed wavelength inverts the whole argument, and it flips the conclusion about Δ: absorbing high-energy violet means a LARGE splitting and a strong-field ligand, while a red-looking complex absorbing green has a small one.' },
  { id: 'nuc-019', topic: 'nuclear', skill: 'descriptive/coordination', q: 'One EDTA⁴⁻ replaces how many water ligands on a metal ion?', opts: ['2', '4', '6', '1'], a: 2, why: 'Hexadentate: 2 N + 4 carboxylate O donors wrap the whole octahedron. 1 particle in, 6 out → huge ΔS → K(f) ~10²⁰.' },
  { id: 'nuc-020', tier: 3, topic: 'nuclear', skill: 'descriptive/coordination', q: 'How many isomers of octahedral [Co(NH₃)₄Cl₂]⁺ exist?', opts: ['1, only one arrangement', '3, counting the mirror image', '2, cis and trans', '4, one per Cl position'], a: 2, why: 'MA₄B₂: the two Cl can be adjacent (cis, 90°) or opposite (trans, 180°). Famously different colors — violet vs green.', misconception: 'cis-MA₄B₂ has a mirror plane, so there is no enantiomer to add to the count — octahedral chirality needs something like cis-M(AA)₂B₂ or M(AA)₃. Nor are the six vertices six distinct choices: the octahedron\'s symmetry means only the Cl–Cl relationship matters, 90° or 180°, which is why "one isomer per position" overcounts.' },
  { id: 'nuc-021', topic: 'nuclear', skill: 'descriptive/coordination', q: 'Oxidation state of Cr in [Cr(NH₃)₄Cl₂]⁺?', opts: ['+1', '+3', '+2', '0'], a: 1, why: 'NH₃ neutral, 2 Cl⁻ = −2, overall +1 → Cr = +3 (the most stable Cr state, d³).' },
  { id: 'nuc-022', topic: 'nuclear', skill: 'descriptive/coordination', q: '[CoBr(NH₃)₅]SO₄ and [CoSO₄(NH₃)₅]Br are…', opts: ['ionisation isomers', 'linkage isomers of sulfate', 'enantiomers of one another', 'identical compounds'], a: 0, why: 'Swap which anion is INSIDE the coordination sphere vs outside. Distinguish with AgNO₃/BaCl₂ precipitation tests.' },
  { id: 'nuc-023', topic: 'nuclear', skill: 'descriptive/nuclear', q: 'Even-even nuclei (even Z, even N) are the most numerous stable nuclei because…', opts: ['they are the heaviest nuclides', 'they have no net nuclear spin', 'they are the most resistant to fission', 'nucleon pairing adds stability'], a: 3, why: 'Nucleons pair like electrons do: ~160 stable even-even nuclides vs only ~5 odd-odd. Magic numbers (2,8,20,28,50,82,126) stack on top.' },
  { id: 'nuc-024', topic: 'nuclear', skill: 'descriptive/nuclear', q: 'The mass of a helium-4 nucleus is LESS than 2p + 2n separately. The difference is…', opts: ['error in the measurement', 'the mass of two electrons', 'binding energy, E = Δmc²', 'the mass carried by neutrinos'], a: 2, why: 'The mass defect Δm was released as ~28 MeV of binding energy when the nucleus formed — millions of times any chemical bond.', misconception: 'The mass defect is not experimental error and not the mass of anything left over — it is binding energy, converted through E = Δmc². Assembling ⁴He from two protons and two neutrons releases about 28 MeV, and that energy leaves as mass. This is why a bound nucleus is always lighter than its separated parts, and why the biggest defect per nucleon (iron-56) marks the most stable nucleus.' },
  { id: 'nuc-025', topic: 'nuclear', skill: 'descriptive/crystal-field', q: 'Which is the correct spectrochemical trend (weak → strong field)?', opts: ['CN⁻ < H₂O < Cl⁻ < NH₃ < en', 'Cl⁻ < H₂O < NH₃ < CN⁻', 'NH₃ < Cl⁻ < CN⁻', 'H₂O < Cl⁻ < en'], a: 1, why: 'I⁻ < Br⁻ < Cl⁻ < F⁻ < OH⁻ < H₂O < NH₃ < en < NO₂⁻ < CN⁻ ≈ CO. Halides weak, C-donors strong.' },
];

export const ORGANIC1_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'og1-001', topic: 'organic1', skill: 'lab/structure-elucidation', q: 'General formula of alkanes?', opts: ['CₙH₂ₙ₊₂', 'CₙH₂ₙ', 'CₙH₂ₙ₋₂', 'CₙHₙ'], a: 0, why: 'This is asking for the general formula of an alkane. An alkane is a chain of carbons joined by single bonds only, with hydrogen filling every remaining position. Each carbon carries two hydrogens, plus one extra at each end of the chain, giving CₙH₂ₙ₊₂.' },
  { id: 'og1-002', topic: 'organic1', skill: 'organic/nomenclature', q: 'The functional group of alcohols is…', opts: ['–COOH', '–OH', '–NH₂', '–CHO'], a: 1, why: 'This is asking which group defines an alcohol. A functional group is the small cluster of atoms that gives a molecule its characteristic reactions. Alcohols carry the hydroxyl group, –OH. The others listed are carboxylic acid (–COOH), amine (–NH₂) and aldehyde (–CHO).' },
  { id: 'og1-003', topic: 'organic1', skill: 'bonding/hybridisation', q: 'Bond angle at an sp³ carbon?', opts: ['90.0°', '120°', '109.5°', '180.0°'], a: 2, why: 'This is asking for the bond angle around an sp³ carbon. An sp³ carbon has four bonding groups, which spread as far apart as they can in three dimensions. That arrangement is a tetrahedron, with angles of 109.5°, as in methane.' },
  { id: 'og1-004', topic: 'organic1', q: 'Compounds with the same formula but different structures are…', opts: ['isotopes', 'polymers', 'allotropes', 'isomers'], a: 3, why: 'This is asking what to call molecules that share a formula but not a structure. Isomers have the same atoms counted up but joined together differently. They may differ in which atom is bonded to which, or only in their three-dimensional layout.' },
  { id: 'og1-005', topic: 'organic1', skill: 'organic/nomenclature', q: 'An alkene must contain…', opts: ['a C=C bond', 'a C≡C triple bond', 'an –OH group', 'a benzene ring somewhere'], a: 0, why: 'This is asking what makes a hydrocarbon an alkene. An alkene is defined by having a carbon–carbon double bond, C=C. A triple bond, C≡C, makes an alkyne instead, and neither one needs an –OH group or a ring.' },
  // ---- olympiad ----
  { id: 'og1-006', tier: 3, topic: 'organic1', skill: 'organic/substitution-elimination', q: '(CH₃)₃C–Br in warm ethanol (no added base) reacts mainly by…', opts: ['SN2', 'SN1 (+E1)', 'E2', 'no reaction'], a: 1, why: '3° blocks SN2; weak nucleophile can\'t force anything → ionization to the 3° cation (solvolysis), more E1 with heat.', misconception: 'Substrate class decides mechanism before any reagent does. A tertiary halide cannot do SN2 at all — the backside approach is physically blocked — so with a weak nucleophile like warm ethanol it ionises instead, giving SN1 with E1 alongside. "Stronger nucleophile, faster SN2" only applies where SN2 is possible in the first place; on a 3° centre it is not.' },
  { id: 'og1-007', topic: 'organic1', skill: 'acids/strong-weak', q: 'Strongest acid?', opts: ['ethanol, pKa 16.0', 'phenol, pKa 10.0', 'acetic acid, 4.8', 'water, pKa 15.7'], a: 2, why: 'Carboxylate delocalizes charge over two equivalent oxygens — better than phenoxide\'s ring, far better than alkoxide.' },
  { id: 'og1-008', topic: 'organic1', skill: 'organic/mechanisms', q: 'Most stable carbocation?', opts: ['CH₃⁺, methyl', 'CH₃CH₂⁺, primary', 'CH₂=CH⁺, vinyl cation', '(CH₃)₃C⁺, 3°'], a: 3, why: 'Three alkyl donors (hyperconjugation + induction). A simple vinyl cation is worse than any alkyl cation except methyl.', misconception: 'Carbocation stability is not simply "more atoms attached". It comes from electron donation into the empty p orbital by hyperconjugation and resonance, so 3° &gt; 2° &gt; 1° &gt; methyl — and a simple vinyl cation sits below every alkyl cation except methyl, because the positive charge lands on an sp carbon that holds its electrons too tightly to share. They are still real intermediates — acid-catalysed alkyne hydration and vinyl triflate solvolysis both go through one — so the rule is that they are hard to form, not that they never occur.' },
  { id: 'og1-009', topic: 'organic1', skill: 'organic/substitution-elimination', q: 'SN2 on an (R) stereocenter gives…', opts: ['inversion', 'retention', 'racemization', 'elimination'], a: 0, why: 'Backside attack flips the umbrella (Walden inversion). Racemization is SN1\'s signature.', misconception: 'SN2 gives clean <em>inversion</em>, not racemisation — the nucleophile attacks the face opposite the leaving group and the centre turns inside out. Racemisation is the fingerprint of SN1, where a planar carbocation can be attacked from either side. Note also that inversion of configuration does not always mean the R/S label flips: that depends on the CIP priorities of the incoming and leaving groups.' },
  { id: 'og1-010', topic: 'organic1', skill: 'organic/substitution-elimination', q: 'E2 requires the β-H and leaving group to be…', opts: ['cis to each other', 'gauche, about 60°', 'anti-periplanar', 'geminal, on one carbon'], a: 2, why: 'Concerted TS needs aligned orbitals at 180°. On cyclohexanes: both must be AXIAL.' },
  { id: 'og1-011', topic: 'organic1', skill: 'organic/stereochemistry', q: 'A molecule with 3 stereocenters has at most how many stereoisomers?', opts: ['3', '8', '6', '9'], a: 1, why: '2ⁿ = 2³ = 8 — fewer if meso forms exist (internal mirror symmetry).' },
  { id: 'og1-012', topic: 'organic1', skill: 'organic/substitution-elimination', q: 'Best leaving group?', opts: ['I⁻', 'HO⁻', 'F⁻', 'H⁻'], a: 0, why: 'Leaving ability tracks weak basicity: I⁻ > Br⁻ > Cl⁻ ≫ F⁻. HO⁻ and H⁻ are terrible (strong bases) — protonate OH first!', misconception: 'Leaving-group ability tracks <em>weak basicity</em>, i.e. the stability of the anion once it has left. I⁻ is the best of the halides and F⁻ the worst — the reverse of electronegativity-based intuition — and HO⁻ and H⁻ are so basic that they essentially never leave. This is why alcohols are protonated (or tosylated) before substitution: you must convert OH into something that is willing to go.' },
  { id: 'og1-013', topic: 'organic1', skill: 'organic/substitution-elimination', q: 'SN2 is fastest in polar APROTIC solvents (DMSO, acetone) because…', opts: ['they dissolve far more of the substrate', 'they are cheaper and easier to dry', 'they stabilise the carbocation formed', 'they leave the nucleophile bare'], a: 3, why: 'Protic solvents H-bond and cage the nucleophile. Aprotic solvents solvate only the cation, leaving the anion hot.' },
  { id: 'og1-014', topic: 'organic1', skill: 'organic/substitution-elimination', q: '2-bromobutane + NaOEt gives mainly…', opts: ['1-butene, the Hofmann product', 'butane, by reduction', '2-butene, the Zaitsev product', '2-butanol, by substitution'], a: 2, why: 'Small strong base → E2 toward the MORE substituted (more stable) alkene: Zaitsev\'s rule. And trans > cis within that.', misconception: 'Which alkene forms is decided by the <em>base</em>, not by the substrate alone. A small strong base (NaOEt) removes the most accessible proton that gives the most substituted, most stable alkene — Zaitsev. A bulky base (KOtBu) cannot reach that hydrogen and takes a terminal one instead, giving the LESS substituted Hofmann product. Quoting Zaitsev as a universal rule misses half the exam questions on elimination.' },
  { id: 'og1-015', topic: 'organic1', skill: 'organic/substitution-elimination', q: 'Same substrate with bulky KOtBu gives mainly…', opts: ['2-butene, the Zaitsev product', '1-butene, the Hofmann product', 'the ether, by substitution', 'no reaction at all'], a: 1, why: 'The fat base can only reach the exposed terminal CH₃ hydrogens → LESS substituted alkene. Base size flips regiochemistry.' },
  { id: 'og1-016', tier: 3, topic: 'organic1', skill: 'organic/mechanisms', q: 'The 2° cation from 3-methyl-2-butanol under acid rearranges by…', opts: ['a hydride shift to 3°', 'a methyl shift down to 1°', 'closing onto a ring', 'no rearrangement at all'], a: 0, why: 'The adjacent C–H slides over: 2° → 3° cation is downhill. Expect "wrong" SN1/E1 products whenever this is possible.', misconception: 'Carbocations rearrange whenever a hydride or alkyl shift can reach a more stable cation, and they do it faster than most nucleophiles arrive. A secondary cation next to a tertiary carbon will not wait around to be captured — it becomes tertiary first, and the product comes from <em>there</em>. Any SN1 or E1 answer drawn without checking for a possible shift is a likely wrong product.' },
  { id: 'og1-017', topic: 'organic1', skill: 'organic/stereochemistry', q: 'A meso compound is…', opts: ['chiral, with two stereocentres', 'always optically active in solution', 'a 50:50 mixture of enantiomers', 'achiral despite stereocentres'], a: 3, why: 'An internal mirror plane makes the molecule superimposable on its reflection — e.g. (2R,3S)-tartaric acid. Reduces the 2ⁿ count.' },
  { id: 'og1-018', tier: 3, topic: 'organic1', skill: 'organic/stereochemistry', q: 'Assigning R/S with the LOWEST priority group pointing at you: trace 1→2→3 clockwise reads…', opts: ['R', 'cannot assign', 'S', 'E'], a: 2, why: 'Viewing from the wrong side — REVERSE the call: clockwise reads R but the answer is S.', misconception: 'The 1 → 2 → 3 rotation only reads directly when the LOWEST priority points away from you. With it pointing at you, you are looking at the molecule from behind and the sense you see is inverted, so a clockwise trace is S. Reporting the rotation you traced without first checking where group 4 points is the commonest R/S error there is.' },
  { id: 'og1-019', topic: 'organic1', skill: 'organic/substitution-elimination', q: 'In methanol (protic), the better nucleophile is…', opts: ['F⁻', 'I⁻', 'equal', 'neither reacts'], a: 1, why: 'Protic solvent grips small hard F⁻ in an H-bond cage; big polarizable I⁻ slips free. In DMSO the order flips!', misconception: 'Nucleophilicity is solvent-dependent, and the order can invert completely. In a protic solvent like methanol, small hard F⁻ is locked in a hydrogen-bonded cage while big polarisable I⁻ is barely solvated, so I⁻ is the better nucleophile. In a polar aprotic solvent like DMSO, which solvates only cations, the anions are all left bare and the order reverses to F⁻ &gt; I⁻. "Iodide is always the better nucleophile" is only half the story.' , why2: 'Nucleophilicity in solution is a <em>difference</em>: how much the ion wants the carbon, minus how much the solvent refuses to let go of it. Methanol has an O–H to donate, and it hydrogen-bonds hard to small, charge-dense F⁻ — that cage has to be stripped off before any attack can happen, and the cost exceeds what F⁻ gains from being the stronger base. I⁻ is big and its charge is smeared thin, so methanol barely holds it and it walks in. The clean test of this model is to remove the cage: in DMSO (aprotic — no O–H to donate) nothing is solvated that way, the penalty vanishes, and the order snaps back to basicity, F⁻ &gt; Cl⁻ &gt; Br⁻ &gt; I⁻. Any explanation that does not predict that reversal is not explaining the right thing.' },
  { id: 'og1-020', topic: 'organic1', skill: 'organic/substitution-elimination', q: 'Benzylic halides are unusually fast in…', opts: ['SN1 only, via the cation', 'BOTH SN1 and SN2', 'SN2 only, being unhindered', 'neither, being too hindered'], a: 1, why: 'Resonance stabilizes the cation (SN1) AND the SN2 transition state. Same for allylic.' },
  { id: 'og1-021', topic: 'organic1', skill: 'organic/substitution-elimination', q: 'Vinyl and aryl halides undergo SN1/SN2…', opts: ['rapidly, by either route', 'only when strongly heated', 'essentially never, by either route', 'only with concentrated NaOH, by backside attack at the sp² carbon'], a: 2, why: 'sp² C–X is short and strong, backside approach is blocked by the π system, and the cations are terrible. (Different chemistry — elimination/metal catalysis — is needed.)' },
  { id: 'og1-022', topic: 'organic1', skill: 'acids/strong-weak', q: 'CF₃COOH (pKa 0.2) is ~40,000× stronger than CH₃COOH (4.8) because…', opts: ['it is simply the heavier molecule', 'it carries more acidic protons', 'the F lone pairs delocalise by resonance', 'three F withdraw density inductively'], a: 3, why: 'Induction through σ bonds — the effect fades sharply with distance (β-F helps far less).' },
  { id: 'og1-023', topic: 'organic1', skill: 'acids/strong-weak', q: 'To deprotonate a terminal alkyne (pKa 25), use…', opts: ['NaNH₂, pKa 38', 'NaOH, pKa 15.7', 'NaHCO₃, pKa 6.4', 'NaCl, a neutral salt'], a: 0, why: 'You need the conjugate base of a WEAKER acid (higher pKa). NH₂⁻ (38 > 25) works; HO⁻ (15.7 < 25) fails — equilibrium lies wrong.', misconception: 'Acid–base reactions only run in the direction that makes the <em>weaker</em> acid, so you have to compare pKa values before choosing a base. Deprotonating a terminal alkyne (pKa 25) needs the conjugate base of a weaker acid — NaNH₂ works (NH₃, pKa 38) while NaOH does not (water, 15.7), and the hydroxide equilibrium sits about 10⁹ in the wrong direction. Picking a base by how "strong" it sounds, rather than by the pKa gap, is the mistake.' },
  { id: 'og1-024', topic: 'organic1', skill: 'organic/stereochemistry', q: 'Enantiomers differ in…', opts: ['their boiling points', 'optical rotation direction', 'their solubility in ethanol', 'their molar masses'], a: 1, why: 'Identical in every scalar property; they differ only toward chiral probes: plane-polarized light, chiral reagents, enzymes.', misconception: 'Enantiomers are identical in every ordinary physical property: same boiling point, same solubility, same NMR spectrum, same molar mass. They differ only in the presence of something else that is chiral — plane-polarised light, a chiral catalyst, an enzyme, a receptor. This is why separating them needs a chiral environment and why one enantiomer of a drug can be therapeutic while the other is inert or harmful.' },
  { id: 'og1-025', tier: 3, topic: 'organic1', skill: 'organic/substitution-elimination', q: 'cis-1-bromo-4-tert-butylcyclohexane does E2 faster than trans because…', opts: ['the trans isomer is the more strained of the two', 'the trans isomer has no β-hydrogen', 'in cis, Br can sit AXIAL as E2 needs', 'bromine is effectively bigger in trans'], a: 2, why: 't-Bu demands equatorial; in the cis isomer Br is then axial — exactly what anti-periplanar E2 needs. In trans, Br is stuck equatorial → very slow.', misconception: 'E2 needs the leaving group ANTI-PERIPLANAR to a β-hydrogen, which on a cyclohexane ring means both must be axial — the rate difference is about orbital alignment, not sterics or strain. The bulky t-Bu group is locked equatorial, which forces Br axial in the cis isomer and traps it equatorial in the trans one; explanations like "trans is more strained" or "Br is effectively bigger" answer a sterics question that was never asked.' },
  { id: 'og1-026', tier: 3, topic: 'organic1', skill: ['organic/substitution-elimination', 'organic/mechanisms'], q: 'Neopentyl bromide, (CH₃)₃C–CH₂Br, is almost inert to NaI in acetone, yet warming it with AgNO₃ in ethanol gives mainly <b>2-methyl-2-butyl ethyl ether</b>. Which account fits BOTH observations?', opts: ['It is primary, so SN2 is fast; the ether is a later product of E2 followed by addition of ethanol', 'The β-<i>tert</i>-butyl group blocks backside attack, and Ag⁺-assisted ionisation is accompanied by a methyl shift to a 3° cation, which ethanol traps', 'Ag⁺ makes ethanol nucleophilic enough for SN2, giving neopentyl ethyl ether with inversion', 'A primary cation forms and is stabilised enough by hyperconjugation to survive, so ethanol captures it unrearranged'], a: 1, why: 'Two separate facts, one structure. The carbon bearing Br is primary, but the neighbouring quaternary carbon puts three methyls right where the nucleophile must approach — SN2 at neopentyl is ~10⁵ times slower than at ethyl, so NaI does nothing. Silver ion pulls the bromide off; a free primary cation is far too unstable to form, so a methyl migrates from the adjacent carbon <i>as</i> the C–Br bond breaks, giving the tertiary 2-methylbutan-2-yl cation. Ethanol captures that, so the skeleton of the product is rearranged: 2-methyl-2-butyl ethyl ether, not a neopentyl ether.', misconception: 'The steric block on SN2 is being looked for on the wrong carbon. "Primary means SN2 is fine" counts substituents at the α carbon only, but the transition state has the nucleophile approaching along the C–Br axis, straight into whatever sits on the β carbon — a <i>tert</i>-butyl group there is as effective a shield as branching at the reacting centre itself. The partner error is expecting an unrearranged product: the rearrangement is not an optional afterthought a stable cation might skip, it is what makes ionisation possible at all, because the methyl migrates in the same step rather than after a primary cation has formed.' },
  { id: 'og1-027', tier: 3, topic: 'organic1', skill: ['organic/stereochemistry', 'organic/substitution-elimination'], q: '(2R,3S)-2-bromo-3-phenylbutane is treated with NaOEt in ethanol. The major elimination product is…', opts: ['(<i>E</i>)-2-phenylbut-2-ene', '(<i>Z</i>)-2-phenylbut-2-ene', 'a roughly equal mixture of the <i>E</i> and <i>Z</i> alkenes', '3-phenylbut-1-ene'], a: 1, why: 'E2 is <b>stereospecific</b>: the β-H and Br must be anti-periplanar, so a single diastereomer of the substrate can give only one alkene geometry. Draw the Newman along C2→C3 with Br up on the front carbon and the C3–H down at the back; for (2R,3S) that puts the C2 methyl and the C3 phenyl on the same side of the forming π bond. Phenyl outranks methyl on one alkene carbon and methyl outranks H on the other, and the two winners end up cis — so the product is the <i>Z</i> isomer, even though <i>E</i> is the more stable of the two. Ethoxide is a small, strong base, so Zaitsev applies and the internal alkene dominates over 3-phenylbut-1-ene.', misconception: 'Zaitsev is being asked a question it cannot answer. It ranks alkene <em>skeletons</em> — which β-hydrogen is removed, hence how substituted the double bond is — and says nothing about which geometry results. Geometry in an E2 is fixed by the anti-periplanar requirement acting on the substrate\'s own stereochemistry, so the product can perfectly well be the less stable isomer. Whenever a single diastereomer goes in, one geometry comes out; the answer "a mixture of <i>E</i> and <i>Z</i>" would require the reaction to pass through a freely rotating intermediate, which a concerted one-step elimination never does.' },
  { id: 'og1-028', tier: 3, topic: 'organic1', skill: 'organic/substitution-elimination', q: 'Which combination gives the HIGHEST proportion of substitution rather than elimination?', opts: ['1-bromobutane with KO<i>t</i>Bu in <i>tert</i>-butanol', '2-bromobutane with NaOEt in ethanol', '2-bromobutane with NaN₃ in DMSO', '2-bromo-2-methylpropane with NaOEt in ethanol'], a: 2, why: 'Substrate, nucleophile and solvent all have a vote, and here only one option gets all three right. Azide is an outstanding nucleophile but a feeble base (HN₃ has pKa 4.6), so it attacks carbon rather than a β-hydrogen; DMSO is polar aprotic, leaving the anion unsolvated and reactive; and a secondary centre still permits backside attack. The tertiary halide with ethoxide gives essentially pure E2. Both remaining options pair a good substrate with a <b>strong base</b>: ethoxide on a secondary halide gives mostly alkene, and KO<i>t</i>Bu is bulky enough to abstract a proton even from a primary chain rather than attack it.', misconception: 'Nucleophilicity and basicity are being treated as one property, so "strong nucleophile" and "strong base" get used interchangeably and the choice collapses to the substrate class alone — hence the reflex that a primary halide must give substitution. They are different axes: basicity is affinity for H⁺ measured at equilibrium, nucleophilicity is rate of attack at carbon. Azide, iodide, thiolate and cyanide sit high on one axis and low on the other, which is exactly why they are the reagents that deliver SN2 on secondary carbon, while <i>tert</i>-butoxide sits high on the other axis and eliminates whatever you give it.' },
  { id: 'og1-029', tier: 3, topic: 'organic1', skill: 'organic/stereochemistry', q: 'Br₂ in CH₂Cl₂ is added to (<i>Z</i>)-but-2-ene. The 2,3-dibromobutane produced is…', opts: ['the meso (2R,3S) diastereomer', 'a racemic mixture of (2R,3R) and (2S,3S)', 'a single enantiomer, and the solution is optically active', 'both meso and racemic material, because the bromonium ion can open at either carbon'], a: 1, why: 'Bromination goes through a cyclic bromonium ion, opened by bromide from the opposite face — net <b>anti</b> addition. Add the two Br atoms to opposite faces of the cis alkene and assign: the result is (2R,3R) from attack on one face of the alkene and (2S,3S) from the other. The two faces are attacked equally often because the starting alkene is achiral, so the product is a 50:50 racemate — optically inactive, but made of chiral molecules, which is a different kind of inactivity from meso. Running the same addition on (<i>E</i>)-but-2-ene instead gives the meso compound.', misconception: 'The mistake is remembering "anti addition gives the meso product" as a fact about anti addition, when it is a fact about one particular alkene geometry. Anti addition is a rule about the two new bonds being on opposite faces; what that produces depends entirely on how the substituents were already arranged. For a symmetrically substituted alkene the pairing is fixed and worth memorising in the correct form: cis alkene + anti addition → the chiral (R,R)/(S,S) pair, trans alkene + anti addition → meso. Option four is a further trap: opening the bromonium at either carbon gives the two enantiomers of the same pair, which is what makes the mixture racemic — it never generates the meso diastereomer.' },
  { id: 'og1-030', tier: 3, topic: 'organic1', skill: 'organic/mechanisms', q: 'Solvolysis of (R)-1-phenylethyl chloride in aqueous acetone gives alcohol that is largely racemised but carries a small, reproducible excess of the INVERTED enantiomer. The best explanation is…', opts: ['the reaction is really SN2, merely with a slow rate-determining step', 'the cation is planar, so a deviation from exactly 50:50 must be experimental error', 'the departing chloride lingers as a contact ion pair, shielding the face it left from and biasing water towards backside capture', 'the benzylic cation is resonance-stabilised, so it lives long enough to racemise completely'], a: 2, why: 'Reason backwards from the number. Complete racemisation would require a cation that is fully symmetric with respect to attack — free, and surrounded evenly by solvent. Zero racemisation would mean no cation at all. The observation sits between the two, so the intermediate must be a cation that is <em>partly</em> shielded: immediately after ionisation the chloride is still sitting on the face it left, so water reaches the opposite face more easily, and the resulting excess of inverted product decays as the ion pair separates. That is why a more ionising, better cation-solvating medium pushes the same substrate closer to 50:50.', misconception: 'The carbocation is being pictured as a free, symmetrically solvated species the moment the C–Cl bond breaks, which makes exactly 50:50 the only permitted answer and turns the measured excess into noise to be dismissed. Ionisation actually produces a graded series — intimate ion pair, solvent-separated ion pair, then dissociated ions — and the leaving group blocks one face until that separation is complete. Note also that answer four gets the direction of its own logic wrong: greater cation stability would mean a longer-lived, more separated ion and therefore <em>more</em> racemisation, so it cannot explain an excess.' },
];

export const ORGANIC2_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'og2-001', topic: 'organic2', skill: 'organic/aromatic', q: 'The molecular formula of benzene is…', opts: ['C₆H₁₂', 'C₆H₆', 'C₆H₁₀', 'C₆H₅'], a: 1, why: 'This is asking for the formula of benzene. Benzene is a flat ring of six carbon atoms, each carrying one hydrogen. Counting them gives C₆H₆, with six electrons shared right around the ring.' },
  { id: 'og2-002', topic: 'organic2', skill: 'organic/mechanisms', q: 'Markovnikov\'s rule: in HX addition, H goes to the carbon…', opts: ['with more H\'s already', 'with fewer H\'s', 'that is most substituted', 'bonded to X'], a: 0, why: 'This is asking where the hydrogen ends up when HX adds to an alkene. The proton adds first, and the positive charge left behind lands on the more substituted carbon. That carbon holds the charge better, so this route is the faster one. The H is therefore left on the carbon that already had more hydrogens.', misconception: 'Markovnikov is a statement about carbocation stability, not a rule about where hydrogen "likes" to go. The proton adds so as to leave the positive charge on the more substituted carbon, because that cation is the more stable one. Memorising "H goes to the carbon with more H" gets the right answer for HX and then fails you on hydroboration, where sterics rather than a cation decide, and on radical HBr addition, where a radical does.' },
  { id: 'og2-003', topic: 'organic2', skill: 'organic/synthesis', q: 'Adding H₂/Pd to an alkene gives…', opts: ['an alkyne', 'a ketone', 'an alcohol', 'an alkane'], a: 3, why: 'This is asking what hydrogen and a palladium catalyst do to an alkene. Hydrogenation adds one H atom to each carbon of the C=C, turning the double bond into a single bond. The alkene becomes the matching alkane.' },
  { id: 'og2-004', topic: 'organic2', skill: 'organic/carbonyl', q: 'Full oxidation of a primary alcohol gives…', opts: ['a ketone, then no further', 'an ester with itself', 'a carboxylic acid', 'an alkene, by dehydration'], a: 2, why: 'This is asking how far a primary alcohol can be oxidised. A primary alcohol has its –OH on a carbon joined to only one other carbon. Oxidation removes hydrogen in two stages, first to the aldehyde and then on to the carboxylic acid. A milder reagent such as PCC stops at the aldehyde.' },
  { id: 'og2-005', topic: 'organic2', skill: 'organic/carbonyl', q: 'An ester is made from…', opts: ['two alcohols condensing', 'an acid and an alcohol', 'two acids, losing water', 'an amine plus an alcohol'], a: 1, why: 'This is asking which two molecules combine to make an ester. An ester forms when a carboxylic acid and an alcohol join and a water molecule is lost. With an acid catalyst: RCOOH + R′OH ⇌ RCOOR′ + H₂O.' },
  // ---- olympiad ----
  { id: 'og2-006', topic: 'organic2', skill: 'organic/mechanisms', q: 'Propene + HBr (no peroxides) gives mainly…', opts: ['2-bromopropane', '1-bromopropane', '1,2-dibromopropane', 'propane'], a: 0, why: 'Markovnikov via the 2° carbocation. Peroxides flip it to 1-bromopropane (radical, anti-Markovnikov).' },
  { id: 'og2-007', topic: 'organic2', skill: 'organic/aromatic', q: 'Nitration of toluene gives mostly…', opts: ['meta, chiefly', 'no reaction under these conditions', 'ipso, replacing CH₃', 'ortho and para'], a: 3, why: '–CH₃ is a weak activator and o/p director (hyperconjugation stabilizes the o/p arenium ions).' },
  { id: 'og2-008', topic: 'organic2', skill: 'organic/aromatic', q: '–NO₂ on a benzene ring is…', opts: ['an activator directing o/p', 'a deactivator directing o/p', 'deactivator, meta', 'an activator directing meta'], a: 2, why: 'π-withdrawal destabilizes o/p attack worst (positive charge lands beside NO₂) → meta survives, everything slower.', misconception: 'Activating/deactivating and ortho-para/meta directing are two separate questions, and only one of them is settled by the resonance arrow. NO₂ withdraws by both induction and resonance, so it deactivates the ring <em>and</em> directs meta — but the halogens deactivate (induction) while directing ortho/para (their lone pairs stabilise those intermediates). Assuming "deactivator ⇒ meta director" gets every halogen wrong.' },
  { id: 'og2-009', topic: 'organic2', skill: 'organic/carbonyl', q: 'A ketone + NaBH₄ gives…', opts: ['1° alcohol', '2° alcohol', 'carboxylic acid', 'alkane'], a: 1, why: 'Hydride to the carbonyl carbon: R₂C=O → R₂CH–OH. Aldehydes give 1° alcohols.' },
  { id: 'og2-010', topic: 'organic2', skill: 'bonding/lewis-vsepr', q: 'Point group of H₂O?', opts: ['C₂', 'Cₛ', 'D₂ₕ', 'C₂ᵥ'], a: 3, why: 'One C₂ axis + two σᵥ planes containing it.' },
  { id: 'og2-011', topic: 'organic2', skill: 'organic/stereochemistry', q: 'Which molecule is CHIRAL?', opts: ['gauche H₂O₂', 'XeF₄', 'trans-dichloroethene', 'CH₂Cl₂'], a: 0, why: 'Gauche H₂O₂ has ONLY a C₂ rotation — no σ, i, or Sₙ. Pure rotations don\'t kill chirality.' },
  { id: 'og2-012', topic: 'organic2', skill: 'organic/mechanisms', q: 'Hydroboration–oxidation (BH₃, then H₂O₂/OH⁻) of propene gives…', opts: ['propan-2-ol', 'propan-1-ol', 'propanal', 'propanoic acid'], a: 1, why: 'Anti-Markovnikov and syn: boron (the future OH) adds to the LESS hindered carbon — sterics, not cations.', misconception: 'Hydroboration–oxidation puts the OH on the LESS substituted carbon, and no carbocation is involved anywhere. Boron and hydrogen add across the double bond in one concerted, syn step, with boron going to the less hindered end for steric reasons — then H₂O₂/OH⁻ replaces B with OH, retaining that position and that stereochemistry. Calling this "anti-Markovnikov because the cation is different" invents a mechanism that does not exist.' },
  { id: 'og2-013', tier: 3, topic: 'organic2', skill: 'lab/structure-elucidation', q: 'Ozonolysis of an alkene (O₃, then Zn/H₂O) gives 2 equivalents of acetone. The alkene was…', opts: ['2-butene, but-2-ene', 'propene, CH₃CH=CH₂', '2,3-dimethylbut-2-ene', 'isobutylene, 2-methylpropene'], a: 2, why: 'Rebuild by gluing the carbonyls: (CH₃)₂C=O + O=C(CH₃)₂ → (CH₃)₂C=C(CH₃)₂. Ozonolysis is a structure-determination scalpel.', misconception: 'Rebuilding an ozonolysis substrate means gluing the two carbonyl CARBONS together with a double bond — the oxygens are cleaved away, not carried into the alkene. Two acetone fragments therefore demand (CH₃)₂C= on both sides; isobutylene would give one acetone and one formaldehyde, and but-2-ene would give two acetaldehydes, not two acetones.' },
  { id: 'og2-014', topic: 'organic2', skill: 'organic/mechanisms', q: 'Br₂ addition to cyclohexene gives…', opts: ['cis-1,2-dibromocyclohexane, meso', '1,1-dibromocyclohexane, geminal', 'bromobenzene, by substitution', 'trans-1,2-dibromocyclohexane'], a: 3, why: 'The bromonium ion forces backside attack → ANTI addition → trans product (both enantiomers).', misconception: 'Br₂ adds ANTI, not syn, and the reason is the bridged bromonium ion. The first bromine forms a three-membered ring across the alkene face, and bromide has to attack from the opposite side, so the two bromines end up trans. Drawing both bromines adding to the same face is the intuitive answer and gives the wrong diastereomer.' },
  { id: 'og2-015', tier: 3, topic: 'organic2', skill: 'organic/aromatic', q: 'Friedel–Crafts ALKYLATION with 1-chloropropane/AlCl₃ gives mostly…', opts: ['isopropylbenzene', 'n-propylbenzene, unrearranged', 'toluene, by C–C cleavage', 'no reaction with a 1° halide'], a: 0, why: 'The 1° cation-like complex rearranges (hydride shift) to 2° before attacking. FC ACYLATION avoids this — acylium doesn\'t rearrange.', misconception: 'Friedel–Crafts alkylation is unreliable exactly because the electrophile rearranges. A primary alkyl halide generates a cation-like complex that shifts a hydride to become secondary before it ever reaches the ring, so 1-chloropropane gives cumene, not n-propylbenzene. Acylation avoids this — the acylium ion is resonance-stabilised and does not rearrange — which is why the standard route to a straight-chain alkyl group is acylate first, then reduce.' , why2: 'Draw the electrophile and ask whether it has somewhere better to be. The 1-chloropropane/AlCl₃ complex is essentially a primary cation, CH₃CH₂CH₂⁺ — and a hydride sitting on the adjacent carbon can slide over to give the secondary cation, a large drop in energy. Benzene is a <em>weak</em> nucleophile and slow to attack, so the rearrangement wins the race and the ring meets the isopropyl cation, giving cumene. Working rule: in Friedel–Crafts alkylation, if the cation can rearrange, assume it has. The industrial answer to this is the reason acylation exists — an acylium R–C≡O⁺ is resonance-stabilised with a complete octet at carbon and has nothing to gain by shifting, so acylate first and reduce the ketone afterwards (Clemmensen or Wolff–Kishner) to get the straight chain.' },
  { id: 'og2-016', topic: 'organic2', skill: 'organic/aromatic', q: 'Friedel–Crafts reactions FAIL on…', opts: ['toluene, being activated', 'nitrobenzene', 'anisole, strongly activated', 'benzene itself'], a: 1, why: 'Strongly deactivated rings can\'t stabilize the arenium ion. (They also fail on anilines — AlCl₃ grabs the N lone pair.)' },
  { id: 'og2-017', topic: 'organic2', skill: 'organic/aromatic', q: 'Bromination of aniline WITHOUT protection gives…', opts: ['the mono-para product only', 'the meta product predominantly', '2,4,6-tribromoaniline', 'no reaction without a catalyst'], a: 2, why: '–NH₂ is so activating that bromine water tribrominates on contact. Protect as the amide (acetanilide) to stop at mono.' },
  { id: 'og2-018', tier: 3, topic: 'organic2', skill: 'organic/carbonyl', q: 'The aldol product of two acetaldehyde molecules is…', opts: ['ethyl acetate', 'butanal', 'crotonaldehyde only', '3-hydroxybutanal'], a: 3, why: 'Enolate of one attacks the carbonyl of the other → β-hydroxy aldehyde (3-hydroxybutanal); heat dehydrates it to crotonaldehyde (E1cb).', misconception: 'Aldol ADDITION and aldol CONDENSATION are two stages, and the question stops at the first: the enolate attacks a carbonyl to give the β-hydroxy aldehyde, and crotonaldehyde only appears once that alcohol is dehydrated, which takes heat or forcing base. Naming crotonaldehyde treats the condensation as automatic, while butanal has no OH at all and could not come from adding one carbonyl compound to another.' },
  { id: 'og2-019', topic: 'organic2', skill: 'organic/carbonyl', q: 'Acetals protect ketones because they are stable to…', opts: ['base and nucleophiles', 'aqueous acid on warming', 'essentially every reagent', 'oxidising conditions only'], a: 0, why: 'Acetals ignore bases, Grignards, hydrides — then mild aqueous acid unzips them back to the ketone. Orthogonal protection.' },
  { id: 'og2-020', tier: 3, topic: 'organic2', skill: 'organic/carbonyl', q: 'Ester + 2 CH₃MgBr gives, after workup…', opts: ['a 3° alcohol, two CH₃ added', 'a ketone, stopping at one addition', 'the carboxylic acid, on workup', 'an ether from the alkoxide'], a: 0, why: 'The intermediate ketone is MORE reactive than the ester — the second equivalent attacks before you can stop it.', misconception: 'Grignard reagents cannot be stopped at the ketone stage when they attack an ester, because the ketone they produce is <em>more</em> electrophilic than the ester they came from. The second equivalent adds immediately, giving a tertiary alcohol with two identical new groups. Stopping at the ketone requires a deliberately damped reagent (a Weinreb amide, or a Gilman cuprate).' },
  { id: 'og2-021', topic: 'organic2', skill: 'organic/carbonyl', q: 'Tollens\' reagent (Ag(NH₃)₂⁺) distinguishes…', opts: ['alkenes from alkanes', '1° from 2° alcohols directly', 'carboxylic acids from esters', 'aldehydes from ketones'], a: 3, why: 'Aldehydes reduce Ag⁺ to a silver mirror; ketones don\'t. Fehling\'s (Cu²⁺ → red Cu₂O) does the same job.' },
  { id: 'og2-022', topic: 'organic2', skill: 'organic/carbonyl', q: 'Reactivity order of carboxylic acid derivatives toward nucleophiles?', opts: ['amide > ester > anhydride > acid chloride', 'ester > acid chloride > amide', 'acid chloride > anhydride > ester > amide', 'all four react at the same rate'], a: 2, why: 'Better leaving group + less resonance donation = more reactive. Amides are the most stable — that\'s why proteins survive.', misconception: 'Carboxylic acid derivative reactivity follows leaving-group ability and resonance donation together: acid chloride &gt; anhydride &gt; ester &gt; amide. The amide is least reactive because nitrogen donates its lone pair into the carbonyl most effectively and NH₂⁻ is a hopeless leaving group — which is precisely why the peptide bonds holding proteins together survive in water. Ranking by "which looks most reactive" without the leaving group in mind inverts the series.' },
  { id: 'og2-023', topic: 'organic2', skill: 'organic/carbonyl', q: 'To form an enolate quantitatively (not an equilibrium), deprotonate a ketone (pKa ~20) with…', opts: ['NaOEt (pKa 16)', 'LDA (pKa ~36)', 'NaHCO₃', 'H₂O'], a: 1, why: 'LDA\'s conjugate acid is 10¹⁶ weaker → complete, fast, and too bulky to attack the carbonyl itself. NaOEt gives only ~10⁻⁴ enolate.' },
  { id: 'og2-024', topic: 'organic2', skill: 'bonding/polarity', q: 'Which molecule has an inversion center i?', opts: ['trans-dichloroethene', 'cis-dichloroethene, C₂ᵥ', 'NH₃, pyramidal', 'CHFClBr, fully asymmetric'], a: 0, why: 'Trans: every atom maps through the center onto its twin → C₂ₕ, zero dipole. Cis (C₂ᵥ) has a dipole — tell them apart by polarity!' },
  { id: 'og2-025', topic: 'organic2', skill: 'organic/stereochemistry', q: 'A molecule is guaranteed ACHIRAL if it has…', opts: ['a C₂ rotation axis', 'delocalised resonance', 'more than four atoms in it', 'any improper operation'], a: 3, why: 'Chirality test: no mirror, no inversion, no rotation-reflection. Proper rotations alone (like C₂ in H₂O₂) leave it chiral.', misconception: 'The test for chirality is the absence of any <em>improper</em> symmetry operation — a mirror plane, an inversion centre, or an improper rotation Sₙ. Proper rotation axes do not disqualify a molecule: gauche H₂O₂ has a C₂ axis and is still chiral. Looking only for "an internal mirror plane" is nearly right and misses the Sₙ cases that olympiad questions are built on.' },
  { id: 'og2-026', tier: 3, topic: 'organic2', skill: 'organic/aromatic', q: 'Nitration of 4-chlorotoluene (HNO₃/H₂SO₄) gives mainly…', opts: ['4-chloro-3-nitrotoluene, with NO₂ ortho to the chlorine', '4-chloro-2-nitrotoluene, with NO₂ ortho to the methyl', 'the two mononitro products in roughly equal amounts, since both substituents direct <i>o</i>/<i>p</i>', 'no reaction — the chlorine deactivates the ring too strongly for nitration'], a: 1, why: 'Both groups are <i>o</i>/<i>p</i> directors and both para positions are occupied, so the contest is between the positions ortho to methyl (C2/C6) and those ortho to chlorine (C3/C5). Directing preference is set by which group stabilises the arenium ion better when attack occurs next to it. Methyl donates by hyperconjugation and is activating; chlorine donates by resonance but withdraws more strongly by induction, leaving it net deactivating. So the ring is at its most nucleophilic ortho to the methyl, and the major product is 4-chloro-2-nitrotoluene. Deactivated is not deactivated to a standstill — chlorobenzene nitrates perfectly well, just more slowly than benzene.', misconception: 'Two independent properties of a substituent are being merged into one. <b>Where</b> a group directs and <b>how fast</b> the ring reacts are decided separately: chlorine is an <i>o</i>/<i>p</i> director because its lone pair can stabilise the ortho and para arenium ions by resonance, and simultaneously a deactivator because its inductive pull outweighs that donation overall. When two <i>o</i>/<i>p</i> directors compete, the position is chosen by the stronger <em>activator</em> rather than by whichever group looks like the more emphatic director, so the methyl wins outright and the product is not a near-even mixture.' },
  { id: 'og2-027', tier: 3, topic: 'organic2', skill: 'organic/carbonyl', q: 'Chloral, Cl₃C–CHO, is isolated as its crystalline <b>hydrate</b> Cl₃C–CH(OH)₂, whereas acetone is essentially unhydrated in water. The reason is that…', opts: ['the three chlorines withdraw density inductively, destabilising the electron-poor carbonyl carbon and shifting the equilibrium towards the sp³ hydrate', 'the chlorine lone pairs donate into the C=O by resonance, and that stabilises the hydrate', 'the three chlorines hydrogen bond to the added water and hold the diol together', 'the bulky CCl₃ group relieves its own steric strain by going from sp² to sp³'], a: 0, why: 'Hydration is an equilibrium, so compare both sides. The carbonyl carbon already bears a substantial δ+; putting a powerfully electron-withdrawing CCl₃ next to it makes that positive carbon still less tolerable, raising the energy of the C=O form. In the hydrate that carbon is sp³ and no longer carries the same charge, so the withdrawing group destabilises it far less. Acetone runs the argument backwards: two methyls donate electron density and stabilise the carbonyl, so its hydrate is present at well under one percent.', misconception: 'Resonance donation is being transplanted from a setting where it works to one where there is no orbital to donate into. On a benzene ring or in an acyl chloride a halogen lone pair is conjugated with the π system, but in chloral the chlorines are on an sp³ carbon that is itself attached to the carbonyl carbon — there is no conjugation path, only a σ framework, so the effect is purely inductive. Even granting the resonance, it would work the wrong way: donation into a C=O stabilises the carbonyl and would <em>disfavour</em> hydration. The steric answer fails on direction too, since hydration converts a trigonal carbon into a more crowded tetrahedral one.' },
  { id: 'og2-028', tier: 3, topic: 'organic2', skill: 'organic/carbonyl', q: '2-methylcyclohexanone is added to LDA in THF at −78 °C, then treated with CH₃I. The major product is…', opts: ['2,2-dimethylcyclohexanone', '2,6-dimethylcyclohexanone', 'the O-methylated enol ether', 'the aldol condensation dimer'], a: 1, why: 'Two α positions compete: C2, which already bears a methyl, and C6, which does not. LDA is bulky and very strong, the temperature is low and the deprotonation is irreversible, so the enolate that forms is the one reached fastest — removal of the more accessible C6 hydrogen. That kinetic enolate is captured directly by the alkyl halide, giving 2,6-dimethylcyclohexanone. Equilibrating conditions (a catalytic amount of a weaker base such as NaOEt, warm) would instead funnel everything into the more substituted, more stable C2 enolate and hence 2,2-dimethylcyclohexanone. Adding the ketone to excess LDA, rather than the reverse, is what keeps any unreacted ketone from shuttling protons and eroding the selectivity.', misconception: 'The more stable enolate is being assumed to be the one that reacts, importing Zaitsev-style thinking into a deprotonation. Stability decides the outcome only when the deprotonation is <em>reversible</em>, so that the two enolates can equilibrate — that requires a base weak enough to leave ketone and enolate in genuine equilibrium. With a full equivalent of LDA at −78 °C nothing goes back: whichever proton is removed first is the enolate you alkylate, and the accessible one wins. The choice of base and temperature here is not incidental detail, it is the entire question.' },
  { id: 'og2-029', tier: 3, topic: 'organic2', skill: 'organic/aromatic', q: 'Which species is genuinely ANTIaromatic — destabilised relative to an open-chain reference — rather than merely non-aromatic?', opts: ['cyclooctatetraene, C₈H₈, which adopts a tub-shaped conformation', 'the planar cyclopentadienyl CATION, with 4 π electrons in the ring', 'the cycloheptatrienyl (tropylium) cation', 'cyclohexa-1,3-diene'], a: 1, why: 'Antiaromaticity demands everything aromaticity demands — a cyclic, fully conjugated, <b>planar</b> π system — and then a 4<i>n</i> electron count instead of 4<i>n</i>+2. The cyclopentadienyl cation meets all of it: five sp² carbons, planar, 4 π electrons, and it is famously hard to generate, being far less stable than the open-chain allyl-type cations. Cyclooctatetraene has 8 π electrons but escapes the penalty by puckering into a tub, so its double bonds are no longer conjugated round the ring and it behaves as an ordinary polyene. Tropylium is aromatic with 6 π electrons, and cyclohexa-1,3-diene is not fully conjugated round the ring at all.', misconception: 'The 4<i>n</i> count is being treated as sufficient on its own, so any conjugated ring with 4, 8 or 12 π electrons gets labelled antiaromatic. The count is the last test, not the first: a molecule must be cyclic, fully conjugated and planar before the electron count means anything, and cyclooctatetraene is the standard illustration precisely because it demonstrates the escape route. Being flexible enough to pucker, it does so, sacrificing conjugation to avoid the destabilisation — which makes it non-aromatic, and a molecule that has successfully avoided antiaromaticity is not an example of it.' },
  { id: 'og2-030', tier: 3, topic: 'organic2', skill: ['organic/carbonyl', 'organic/mechanisms'], q: 'Ethyl benzoate labelled with ¹⁸O in its <b>carbonyl</b> oxygen is partly hydrolysed by aqueous NaOH. Ester recovered before the reaction is complete has lost some of its ¹⁸O. This shows that…', opts: ['hydrolysis proceeds by attack of hydroxide at the ethyl carbon, and it is that SN2 step which scrambles the label', 'hydroxide adds reversibly, and the tetrahedral intermediate exchanges protons between its two oxygens before expelling ethoxide', 'the ester hydrolyses and then re-forms from the acid and ethanol, and it is that reverse reaction which scrambles the label', 'the carbonyl oxygen exchanges directly with water in a single concerted step, so no intermediate is involved'], a: 1, why: 'The label moves in molecules that are still esters, so whatever scrambles it must be reversible and must happen <em>before</em> the ester is destroyed. Hydroxide adds to the carbonyl carbon to give a tetrahedral alkoxide bearing two oxygens — the original ¹⁸O and the newly arrived one. Proton transfer makes those two equivalent, and expelling hydroxide instead of ethoxide regenerates the ester with the label sometimes lost to the solvent. That is direct evidence for the addition–elimination pathway and against any one-step displacement at the carbonyl.', misconception: 'Reversibility is being applied at the wrong scale — to the overall reaction rather than to its first step. Saponification is famously irreversible, because the carboxylic acid produced is immediately deprotonated by the base to a carboxylate that no nucleophile will attack, so re-esterification under NaOH is precisely what cannot happen. Scrambling does not require the whole reaction to run backwards; it requires only that the first step does, which is what a tetrahedral intermediate that can expel either oxygen provides. The mechanistic lesson generalises: label scrambling in recovered starting material is the classic fingerprint of a reversibly formed intermediate.' },
];

export const LABDATA_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'lbd-001', topic: 'labdata', skill: 'lab/measurement', q: 'Read a buret at the…', opts: ['top of the meniscus', 'highest graduation', 'side of the tube', 'bottom of the meniscus, at eye level'], a: 3, why: 'This is asking where on a burette you take the reading. Water curves upwards at the glass, and the bottom of that curve is the meniscus. Read the scale at the bottom of the meniscus. Keep your eye level with the mark, because looking from above or below shifts the reading.' },
  { id: 'lbd-002', topic: 'labdata', skill: 'lab/sig-figs', q: '12.5 + 1.25 = ? (correct sig figs)', opts: ['13.75', '14', '13.8', '13.7'], a: 2, why: 'This is asking how many digits to keep after adding. Addition keeps as many decimal places as the least precise value, not the fewest significant figures. 12.5 has one decimal place, so 13.75 is rounded to 13.8.' },
  { id: 'lbd-003', topic: 'labdata', skill: 'lab/spectroscopy-uvvis', q: 'λmax is the wavelength where the sample…', opts: ['transmits most', 'absorbs most', 'reflects most', 'fluoresces'], a: 1, why: 'This is asking what λmax refers to. λmax is the wavelength at which the sample absorbs the most light, the peak of its absorption spectrum. Measuring there gives the largest signal for a given concentration.' },
  { id: 'lbd-004', topic: 'labdata', skill: 'lab/error-analysis', q: 'Precision means the measurements are…', opts: ['reproducible/close to each other', 'close to the true value', 'recorded quickly', 'in SI units'], a: 0, why: 'This is asking what precision means for a set of measurements. Precision is how close repeated measurements are to each other. Accuracy is a different thing: how close they are to the true value.' },
  { id: 'lbd-005', topic: 'labdata', skill: 'lab/spectroscopy-uvvis', q: 'Beer\'s law says absorbance is proportional to…', opts: ['1/concentration', 'temperature', 'concentration²', 'concentration'], a: 3, why: 'This is asking how absorbance changes with concentration. Beer\'s law is A = εbc, so absorbance is proportional to concentration c and to path length b. Doubling the concentration doubles the absorbance, as long as the solution is not too concentrated.' },
  // ---- olympiad ----
  { id: 'lbd-006', tier: 3, topic: 'labdata', skill: 'lab/titration-technique', q: 'Your Erlenmeyer flask is wet with distilled water before adding the acid aliquot. The measured concentration will be…', opts: ['too high', 'too low', 'unaffected', 'unpredictable'], a: 2, why: 'MOLES of acid are unchanged — extra water dilutes the flask but not the amount the titrant must neutralize. The most-tested titration fact.', misconception: 'Water in the titration flask changes the concentration but not the number of <em>moles</em> of analyte, and it is moles the titrant reacts with. So a wet flask has no effect on the result — while a wet buret or pipet, which changes the amount actually delivered, does. Sorting "affects moles" from "affects concentration only" is the entire skill this class of question tests.' , why2: 'Look at which volume appears in the calculation. You compute c(acid) = c(base)·V(base)/V(acid), and V(acid) is the volume you <em>pipetted</em>, not the volume standing in the flask. The rinse water dilutes what is in the flask but changes neither the moles of acid delivered nor the moles of titrant needed to reach the endpoint, so every number in that formula is untouched. The contrast is what makes the fact stick: the pipet and the buret <em>deliver</em>, so water clinging to them dilutes a delivered amount and does change the result — rinse each with the solution it will hold. The conical flask only <em>contains</em>, so distilled water in it is harmless.' },
  { id: 'lbd-007', topic: 'labdata', skill: 'lab/sig-figs', q: 'How many sig figs in 0.020?', opts: ['1', '2', '3', '4'], a: 1, why: 'Leading zeros never count; the trailing zero does (decimal point present) → 2.' },
  { id: 'lbd-008', topic: 'labdata', skill: 'lab/measurement', q: 'A buret is read to the nearest…', opts: ['0.01 mL', '0.1 mL', '1 mL', '0.001 mL'], a: 0, why: 'Graduated every 0.1 mL; you estimate one more digit → 24.37 mL.' },
  { id: 'lbd-009', topic: 'labdata', skill: 'lab/spectroscopy-uvvis', q: 'A = 1.0 means transmittance = …', opts: ['90%', '50%', '1%', '10%'], a: 3, why: 'A = −log T → T = 10%. Above A ≈ 1 the signal is noise-dominated: dilute and re-measure.' },
  { id: 'lbd-010', topic: 'labdata', skill: 'lab/error-analysis', q: 'Five replicates cluster tightly, all 5% above the true value. The data are…', opts: ['accurate and precise', 'precise but not accurate', 'accurate but not precise', 'neither'], a: 1, why: 'Tight = precise; consistent offset = SYSTEMATIC error (e.g., miscalibrated balance). More trials won\'t fix it.', misconception: 'Precision and accuracy fail independently, and only one of them can be fixed by repeating the experiment. Five tightly clustered readings all 5% high are precise and inaccurate: the scatter is small, but a systematic bias — a miscalibrated balance, an uncorrected blank — shifts every one of them the same way. Averaging more trials will report that bias with more confidence, not remove it.' },
  { id: 'lbd-011', topic: 'labdata', skill: 'lab/sig-figs', q: 'Sig figs in 6.022×10²³?', opts: ['3', '23', '4', '27'], a: 2, why: 'Count the mantissa digits only: 6, 0, 2, 2 → 4. The exponent is exact bookkeeping.' },
  { id: 'lbd-012', topic: 'labdata', skill: 'lab/sig-figs', q: '2.5 × 3.42 = ? (correct sig figs)', opts: ['8.55', '9', '8.5', '8.6'], a: 3, why: 'Multiplication keeps the FEWEST sig figs (2.5 has two) → 8.6.' },
  { id: 'lbd-013', topic: 'labdata', skill: 'lab/spectroscopy-uvvis', q: 'The blank cuvette (solvent only) is measured to…', opts: ['zero out absorption by solvent and cell', 'clean the instrument', 'calibrate the wavelength', 'warm up the lamp'], a: 0, why: 'Subtracting the blank isolates the analyte\'s absorbance from background — a systematic-error correction.' },
  { id: 'lbd-014', topic: 'labdata', skill: 'lab/measurement', q: 'To deliver exactly 25.00 mL, use a…', opts: ['graduated cylinder', 'volumetric pipet', 'beaker', 'Erlenmeyer flask'], a: 1, why: 'Volumetric pipet: ±0.03 mL. Graduated cylinder ±0.5; beaker markings are decoration (±5%).' },
  { id: 'lbd-015', topic: 'labdata', skill: 'lab/error-analysis', q: 'Averaging many trials reduces…', opts: ['systematic error', 'both equally', 'random error', 'neither'], a: 2, why: 'Random scatter cancels with √N; a systematic bias just gets averaged INTO the result. Identify bias with a standard, not statistics.', misconception: 'Averaging attacks random error only, shrinking the standard error as 1/√N. A systematic error survives averaging untouched, because every measurement carries it identically. The way to find a bias is a standard, a blank or a second method — never more replicates of the same flawed procedure.' },
  { id: 'lbd-016', topic: 'labdata', skill: 'lab/spectroscopy-uvvis', q: '%T = 25%. Absorbance = ?', opts: ['0.25', '0.40', '0.75', '0.60'], a: 3, why: 'A = −log(0.25) = log 4 ≈ 0.60.' },
  { id: 'lbd-017', topic: 'labdata', skill: 'lab/spectroscopy-uvvis', q: 'A calibration line has a distinctly nonzero intercept. Best response?', opts: ['suspect a blank/systematic offset and subtract or investigate it', 'force it through zero', 'ignore it', 'discard the data'], a: 0, why: 'An offset usually means uncorrected background (dirty cuvette, blank error). Use the fitted line (with intercept) to read unknowns.', misconception: 'A calibration line with a clearly nonzero intercept is telling you something, and forcing it through the origin throws the information away. The usual cause is an uncorrected background — a dirty cuvette, a blank that was not subtracted — and the correct response is to investigate it and then read unknowns off the fitted line, intercept included. Beer\'s law predicts A = 0 at c = 0; if your data disagree, the data are describing your apparatus.' },
  { id: 'lbd-018', topic: 'labdata', skill: 'lab/spectroscopy-uvvis', q: 'A colored solution is diluted 1:1 with water. Its absorbance…', opts: ['doubles', 'halves', 'is unchanged', 'goes to zero'], a: 1, why: 'A ∝ c: half the concentration, half the absorbance. Handy check that you\'re inside the linear range.' },
  { id: 'lbd-019', tier: 3, topic: 'labdata', skill: 'lab/titration-technique', q: 'An air bubble in the buret tip escapes DURING the titration. The reported concentration of analyte is…', opts: ['unaffected', 'too low', 'too high', 'random'], a: 2, why: 'The bubble\'s volume counts as delivered titrant that never was → V reads high → calculated moles of analyte high. Always trace error direction through the formula.', misconception: 'Trace the error through the formula instead of guessing its direction. The bubble\'s volume is recorded as titrant delivered but carried no titrant, so the buret READING is too large and moles of analyte = M × V come out too large with it. Arguing "less titrant actually reacted, so the result must be low" confuses what was delivered with what was read — the calculation only ever sees the reading.' },
  { id: 'lbd-020', topic: 'labdata', skill: 'lab/measurement', q: 'The best way to weigh a hygroscopic solid:', opts: ['slowly, in open air', 'after wetting it', 'by difference, quickly, in a closed container', 'on filter paper'], a: 2, why: 'Weigh (container + sample), pour, re-weigh container: drift and residue cancel; speed and closure limit water uptake.' },
  { id: 'lbd-021', tier: 3, topic: 'labdata', skill: 'lab/sig-figs', q: 'pH of 0.0025 M HCl (2 sig figs), reported correctly:', opts: ['2.6', '2.60', '2.602', '3'], a: 1, why: 'Log rule: sig figs of the number → DECIMAL PLACES of the log. 2 sf → pH = 2.60 (the "2" before the point just marks the power of ten).', misconception: 'For a logarithm, the significant figures of the number become the DECIMAL PLACES of the log. 0.0025 M has two significant figures, so the pH is 2.60 — the "2" before the point only records the power of ten and is not a significant figure at all. Reporting pH 2.6 loses a digit you measured; reporting 2.602 claims one you did not.' },
  { id: 'lbd-022', topic: 'labdata', skill: 'stoich/solution-conc', q: 'Two serial 1:10 dilutions give a total dilution of…', opts: ['1:100', '1:20', '1:10', '1:1000'], a: 0, why: 'Dilution factors multiply: 10 × 10 = 100. Serial dilution beats one huge dilution for accuracy.' },
  { id: 'lbd-023', topic: 'labdata', skill: 'lab/titration-technique', q: 'Before titrating, rinse the PIPET with ______ and the FLASK with ______.', opts: ['water / water', 'acetone / air', 'titrant / titrant', 'the analyte solution / distilled water'], a: 3, why: 'Pipet residue must be the solution it measures (water would dilute it). Flask water doesn\'t matter — moles are already fixed.', misconception: 'The rinse rule follows from whether the vessel\'s contents affect moles delivered. A pipet or buret must be rinsed with the solution it will dispense, because leftover water would dilute what it measures out. The titration flask is rinsed with distilled water only — extra water there changes the concentration but not the moles waiting to react, so it cannot change the result.' },
  { id: 'lbd-024', tier: 3, topic: 'labdata', skill: 'lab/error-analysis', q: 'Each buret reading is ±0.02 mL. The delivered volume (difference of two readings) is uncertain by about…', opts: ['±0.01 mL', '±0.02 mL', '±0.04 mL', '±0.4 mL'], a: 2, why: 'Absolute uncertainties ADD for subtraction: 0.02 + 0.02 = ±0.04 mL. (In quadrature √2×0.02 ≈ 0.03 — either answer beats ±0.02.)', misconception: 'Uncertainties do not cancel when you subtract; they accumulate. A delivered volume is the difference between two buret readings, each ±0.02 mL, so the result is uncertain by ±0.04 mL (or ±0.03 combined in quadrature) — never the ±0.02 of a single reading. Any quantity computed from a <em>difference</em> is less certain than its inputs, which is why titrating to a small volume difference is bad practice.' },
  { id: 'lbd-025', topic: 'labdata', skill: 'lab/spectroscopy-uvvis', q: 'Measuring at a steep shoulder of the absorption band instead of λmax causes…', opts: ['better accuracy', 'high sensitivity to tiny wavelength drift', 'no difference', 'negative absorbance'], a: 1, why: 'On a slope, a 1–2 nm drift changes ε a lot; at the flat peak it barely matters. λmax = max sensitivity AND max robustness.' },
];
